INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_37dde1556f57a25d66618b', 'Absinthe Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Boothby''s 1908 World''s Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'The World''s Drinks and How to Mix Them (William Boothby, 1908)', 'San Francisco, USA', 'William "Cocktail" Boothby', NULL, 'Fill a medium-size mixing-glass with :fine ice ;i.nd pour over it two drops
of Angostura bitters, a dash of orgeat syrup, a dash of anisette and about
half a jigger of absinthe; stir well or shake, strain into a chilled stem
cocktail-glass, squeeze a piece of lemon-peel over t1ie top and serve with a
chaser of ice water.', NULL, NULL, 'coupe', 'shaken', 'lemon peel', 28, 'unreviewed');
