INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_37dde1556f57a25d66618b', 0, 'Fill a medium-size mixing-glass with :fine ice ;i.nd pour over it two drops of Angostura bitters, a dash of orgeat syrup, a dash of anisette and about half a jigger of absinthe; stir well or shake, strain into a chilled stem cocktail-glass, squeeze a piece of lemon-peel over t1ie top and serve with a chaser of ice water.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5da95eaff087980709d817', 'Absinthe Drip', 'cocktail', 'Historic 1908 drink from Boothby''s World''s Drinks and How to Mix Them.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'The World''s Drinks and How to Mix Them (William Boothby, 1908)', 'San Francisco, USA', 'William "Cocktail" Boothby', NULL, 'FRENCH STYLE.
Into a highball or punch-glass place a lump of ice, a pony of absinthe
and a flavor of either gum, orgeat or anisette (whichever the patron prefers);
then fill an absinthe-strainer (a glass or metallic vessel with a single hole in
the bottom) with cracked ice and water, and hold it high up above the glass
containing the absinthe, allowing it to drip until the glass is full; then stir
well and serve.', NULL, NULL, 'highball', 'dripped', NULL, 18, 'unreviewed');
