INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5da95eaff087980709d817', 0, 'FRENCH STYLE.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5da95eaff087980709d817', 1, 'Into a highball or punch-glass place a lump of ice, a pony of absinthe and a flavor of either gum, orgeat or anisette (whichever the patron prefers); then fill an absinthe-strainer (a glass or metallic vessel with a single hole in the bottom) with cracked ice and water, and hold it high up above the glass containing the absinthe, allowing it to drip until the glass is full; then stir well and serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_71f70e20380e5a2438e815', 'Absinthe Frappe, or Frozen Absinthe', 'cocktail', 'Iced frappe from Boothby''s 1908 World''s Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'The World''s Drinks and How to Mix Them (William Boothby, 1908)', 'San Francisco, USA', 'William "Cocktail" Boothby', NULL, 'CALIFORNIA STYLE.
Into a small mixing-glass place a pony of absinthe. (No sweetening of
any description is ever used in making this beverage.) Put three or four
lumps of ice in a small shaker, invert the mixing-glass and absinthe and shake
thoroughly. Now place a bar strainer on top of a punch or highball-glas:s,
into which empty the frozen absinthe and ice; then slowly squirt seltzer over
the ice until the glass is full; stir well and serve.
NoTE.-The only difference between a Frozen Absinthe and a Suissesse
ia that a Suissesse is sweetened and a l!''rozen Absinthe is dry.', NULL, NULL, 'highball', 'frappe', NULL, 22, 'unreviewed');
