INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d487c024018cea55b102c7', 'Absinthe Plain', 'cocktail', 'Historic 1908 drink from Boothby''s World''s Drinks and How to Mix Them.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'The World''s Drinks and How to Mix Them (William Boothby, 1908)', 'San Francisco, USA', 'William "Cocktail" Boothby', NULL, 'A NICE WAY.
Fill a large bar strainer with fine ice and set it on the top of a medium
cut goblet or highball-glass with a duplicate glass alongside of it; now. pour
a pony of absinthe over the ice (and a little orgeat, if the patron desires it),
and when it is strained place the strainer on the other glass and pour the
contents of the first glass over the ice again, and continue to do this until
enough ice has dissolved to fill one of the glasses; then serve.', NULL, NULL, 'highball', 'built', NULL, 18, 'unreviewed');
