INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b24f930d8a9033ce9a9b2d', 2, 'Croix or Jamaica rum.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b24f930d8a9033ce9a9b2d', 3, 'Now beat the yolks of a dozen fancy selected fresh eggs until thin, and the whites until stiff and frothy; stir the yolks into the above mixture and lay the white froth carefully over the top of the liquid.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b24f930d8a9033ce9a9b2d', 4, 'Sprinkle a little red and blue confectioners'' sugar over the froth, but do not add nut-. meg.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b24f930d8a9033ce9a9b2d', 5, 'Hav!l a little grated nutmeg on the side, and those who prefer it can usa it. - If the eggs are not scrupulously fresh great difficulty will be experienced in separating all the yolks from the whites, and when this trouble occurs it will be found impossible to make a nice froth.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b24f930d8a9033ce9a9b2d', 6, 'To make a large quantity of Egg ''Nog multiply the various ingredients in the above recipe by as many gallons as you wish to make, and the desired result will be attained.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b24f930d8a9033ce9a9b2d', 7, 'By filling a siphon soda bottle with some of the above mixture and adding a cake _of compressed yeast to it an effervescent draught fit for the gods can be produced.');
