INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_43eecfc1fa60907f443b0e', 'Daniel Webster Made This Punch', 'cocktail', 'Pre-Prohibition punch from Boothby''s San Francisco bar repertoire.', 12, 15, 0, NULL, 'cocktail', 1, 1, 1908, 'The World''s Drinks and How to Mix Them (William Boothby, 1908)', 'San Francisco, USA', 'William "Cocktail" Boothby', NULL, 'RECIPE USED BY THE GREAT STATESMAN FOR FOURTH OF JULY NECTAR.
This is the recipe for Daniel Webster''s punch which has been preserved
for the great expounder''s successors, and the veteran punch-maker, L. J.
Powers, of Springfield, Mass., annually compounds it on the glorious Fourth.
Two dozen lemons, strained; two pounds of sugar, one-half pint green tea,
strained; one quart· best brandy; three quarts claret; bottle and keep over
night. Then add champagne to suit the taste, strawberries, bananas, oranges,
cherries, pineapples and any fruit desired. Serve in punch-bowl with ice.', NULL, NULL, 'punch-bowl', 'built', 'fruit', 12, 'unreviewed');
