INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_981e04cef3bd3b325f69c2', 1, 'Then place a .small piece of ice in a small cut bar-glass, and pour a jigger of whiskey over it; then add the lemon peel, sugar and water; grate nutmeg over the top and serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_76c15703c957b7e4f6c9ae', 'Soft Toddy', 'cocktail', 'Boothby''s 1908 toddy — sugar, water, spirit.', 1, 3, 3, NULL, 'cocktail', 1, 1, 1908, 'The World''s Drinks and How to Mix Them (William Boothby, 1908)', 'San Francisco, USA', 'William "Cocktail" Boothby', NULL, 'NEW ORLEANS STYLE.
Into a small mixing-glass place a cube of sugar and a small piece of
lemon skin (not lime skin) about twice as large as you would use for a
cocktail; now add about two tablespoonfuls of boiling water and mu.ddle well
with a bar spoon until all the oil has been boiled out of the rind and the
sugar has been dissolved; then add a jigger of good whiskey, and shake the
whole up in a shaker containing two or three lumps of ice until enough ice
has dissolved to make the drink large enough to fill a small cut bar-glass,
into which you then strain it; then with a fruit fork put the lemon skin in
the drink; grate a little nutmeg on top and you will then have compounded a
nectar fit for the gods.', NULL, NULL, 'rocks', 'shaken', 'grated nutmeg', 22, 'unreviewed');
