INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_e26ef25cdf7066ae630cd1', 'Applejack Fix', 'cocktail', 'Pre-Prohibition drink from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'APPLEJACK FIX

Fill large Bar glass with Shaved Ice.



2 teaspoonfuls Bar Sugar, dissolved in little Water.



1/4 Juice of 1 Lemon.



3 dashes of Curacoa.



4 dashes of any Fruit Syrup.



1 jigger Applejack Brandy.



Stir; dress with Fruits; serve with Straws.', NULL, NULL, 'bar', 'stirred', NULL, 28, 'unreviewed');
