INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f2af30180a9b50b4b832ab', 'Applejack Sour', 'cocktail', 'Classic sour from Bullock''s 1917 repertoire.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'APPLEJACK SOUR

Fill large Bar glass 3/4 full Shaved Ice.



2 teaspoonfuls Bar Sugar, dissolved in little Water.



3 dashes lemon or Lime Juice.



1 jigger Applejack.



Stir well; strain into Sour glass; dress with Fruit and Berries and

serve.





"ARF-AND-ARF"



Pour into an Ale glass or mug 1/2 Porter and 1/2 Ale, or Porter and

Stout with Ale, or 1/2 Old and 1/2 New Ale.



The use of the Porter and Ale is more prevalent in England. In the

United States 1/2 Old and 1/2 New Ale is usually used when this drink is

called for, unless otherwise specified.', NULL, NULL, 'sour', 'stirred', 'berries', 12, 'unreviewed');
