INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_c94ed98e9dbe68839ff145', 'Blackthorne Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'BLACKTHORNE COCKTAIL

Fill Mixing glass 2/3 full Shaved Ice.



1/4 teaspoonful Lemon Juice.



1 teaspoonful Syrup.



1/2 jigger Vermouth.



1/2 Jigger Sloe Gin.



1 dash Angostura Bitters.



2 dashes Orange Bitters.



Stir; strain into Cocktail glass and serve.', NULL, NULL, 'cocktail', 'stirred', NULL, 28, 'unreviewed');
