INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_bc0638c5db1308bab7f314', 'Brandy Julep', 'cocktail', 'Bullock''s celebrated julep — Roosevelt''s drink at the St. Louis Country Club.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'BRANDY JULEP

Into a small Bar glass pour 3/4 Wineglass of Water and stir in 1 heaping

teaspoonful of Bar Sugar. Bruise 3 or 4 sprigs of Mint in the Sugar and

Water with a Muddler until the flavor of the Mint has been extracted.

Then withdraw the Mint and pour the flavored Water into a tall Shell

glass or large Goblet, which has been filled with fine Ice, and add:



1 jigger of Brandy.



2 dashes Jamaica Rum.



Stir well; decorate with few sprigs of Mint by planting the sprigs stems

downward in the Ice around the rim of glass; dress with Fruit and serve.', NULL, NULL, 'wine', 'stirred', 'mint sprig', 28, 'unreviewed');
