INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a7a50b9728eff7f223efc7', 'Club Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'CLUB COCKTAIL

Fill large Bar glass 1/2 full Shaved Ice.



2 dashes Angostura Bitters.



2 dashes Pineapple Syrup.



1 jigger Brandy.



Stir; strain into Cocktail glass; dress with Berries; dash with

Champagne; twist a piece of Lemon Skin over the drink and drop it on

top. Serve.', NULL, NULL, 'cocktail', 'stirred', 'lemon peel, berries', 28, 'unreviewed');
