INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3ee93df5e44d8fe013989c', 'Cooperstown Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'COOPERSTOWN COCKTAIL

Use a large Bar glass.



Fill with Lump Ice.



One jigger of Sir Robert Burnette''s Old Tom Gin.



1/2 pony of Italian Vermouth.



Six leaves of fresh Mint.



Shake ingredients well together.



Strain and serve in Cocktail glass.', NULL, NULL, 'cocktail', 'shaken', NULL, 24, 'unreviewed');
