INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f546148eeaa5a9d015ac43', 'Curacoa', 'cocktail', 'Pre-Prohibition drink from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'CURACOA

Into a bottle which will hold a full quart, or a little over, drop 6

ounces of Orange Peel sliced very thin, and add 1 pint of Whiskey. Cork

the bottle securely and let it stand two weeks, shaking the bottle

frequently during that time. Next strain, the mixture, add the Syrup,

pour the strained mixture back into the cleaned bottle and let it stand

3 days, shaking well now and then during the first day. Next, pour a

teacupful of the mixture into a mortar and beat up with it 1 drachm

Powdered Alum, 1 drachm Carbonate of Potash. Put this mixture back into

the bottle and let it stand for 10 days, at the expiration of which time

the Curacoa will be clear and ready for use.', NULL, NULL, 'bar', 'built', 'orange peel', 18, 'unreviewed');
