INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f2516d5128dda1a1afa15c', 'Eggnog (Bowl of 3 Gallons)', 'cocktail', 'Bullock''s eggnog — a holiday staple from St. Louis.', 40, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'EGGNOG (bowl of 3 gallons)

Beat the yolks of 20 Eggs until thin and stir in 2-1/2 lbs. Bar Sugar

until Sugar is thoroughly dissolved. Into this mixture pour:



1-1/2 pints Jamaica Rum.



2 quarts old Brandy.



Mix the ingredients well by stirring. Then pour in the milk slowly,

stirring all the while to prevent curdling. Pour carefully over the top

of the mixture the whites of the Eggs, which have been beaten to a stiff

froth. Fill Punch glasses from the bowl with ladle and sprinkle a little

Nutmeg over each glassful.', NULL, 'Original uses raw whole egg; use pasteurized egg for modern preparation.', 'punch', 'stirred', 'grated nutmeg', 14, 'unreviewed');
