INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7d89aee340be8001b4df74', 'English Bishop Punch', 'cocktail', 'Pre-Prohibition drink from Tom Bullock''s 1917 manual.', 1, 3, 15, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'ENGLISH BISHOP PUNCH

Roast an Orange before a fire or in a hot oven. When brown cut it in

quarters and drop the pieces, with a few Cloves, into a small

porcelain-lined or agate vessel, and pour in 1 quart of hot Port Wine.

Add 6 lumps Cut Loaf Sugar and let the mixture simmer over the fire for

30 minutes. Serve in Stem glasses with Nutmeg grated on top.', NULL, NULL, 'coupe', 'built', 'grated nutmeg', 12, 'unreviewed');
