INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_05027e158f68f461f9de68', 'Fish Club Punch (for a Party of 8)', 'cocktail', 'Large-format punch from Bullock''s bar at the St. Louis Country Club.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'FISH CLUB PUNCH (for a party of 8)

Into a Punch bowl pour:



2-1/2 jiggers Lemon Juice.



4 jiggers Peach Brandy.



2 jiggers Cognac Brandy.



2 jiggers Jamaica Rum.



3 pints Ice Water.



Stir well; ladle into Punch glass and serve.', NULL, NULL, 'punch', 'stirred', NULL, 12, 'unreviewed');
