INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 0, '1 bottle Champagne.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 1, '1 bottle Rum.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 2, '2 tablespoons Dr.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 3, 'Siegert''s genuine Angostura Bitters.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 4, '10 Lemons.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 5, '3 sweet Oranges.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 6, '2 pounds Powdered Sugar.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 7, '10 fresh Eggs.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 8, 'Dissolve the Sugar in the Juice of the Lemons and Oranges adding the Rind of 1 Orange.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 9, 'Strain through a Sieve into a bowl and add by degrees the whites of the Eggs beaten to a froth.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 10, 'Place the bowl on Ice till cold, then stir in the Rum and Wine until thoroughly mixed.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6fb03336ce2f946bcd01b0', 11, 'Serve in fancy Stem glasses.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_ea9acb0e244e6ab4baef59', 'Ramos Gin Fizz--Country Club Style', 'cocktail', 'Effervescent gin fizz from Bullock''s 1917 bar book.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'RAMOS GIN FIZZ--Country Club Style

1 lump Ice.



1 dash Lemon Juice.



1 dash Orange Water.



White of Egg.



1 jigger Burnette''s Old Tom Gin.



1 teaspoonful Powdered Sugar.



1 pony Milk.



1 dash Seltzer Water.



Shake well; strain into Highball glass and serve.', NULL, 'Original uses raw whole egg; use pasteurized egg for modern preparation.', 'highball', 'shaken', NULL, 12, 'unreviewed');
