INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 0, 'Make a batter by separating the yolks from whites of a given number of Eggs;');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 1, 'beating the whites to a stiff froth and stirring the yolks until very thin.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 2, 'Then mix together in a Tom and Jerry bowl, stirring in Bar Sugar slowly until the batter is stiff and serve as follows: Fill Tom and Jerry Mug 1/4 full of Batter.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 3, '1/2 jigger Rum.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 4, '1/2 jigger Brandy.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 5, 'Stir well with Bar spoon;');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 6, 'fill up with Hot Water;');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 7, 'stir more;');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1ef4caa6eb70cd01fbeffc', 8, 'grate Nutmeg on top and serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a9ad274757b9ba570d66ed', 'Twilight Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Tom Bullock''s 1917 manual.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1917, 'The Ideal Bartender (Tom Bullock, 1917)', 'St. Louis, USA', 'Tom Bullock', 'Head bartender at the St. Louis Country Club, Tom Bullock was the first African-American author of a cocktail book. Published in 1917 with a foreword by George Herbert Walker, grandfather of President George H.W. Bush.', 'TWILIGHT COCKTAIL

