INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e20e06f62c1c66972c39b3', 0, 'This is a layered shot');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e20e06f62c1c66972c39b3', 1, 'First pour the Bailey''s into the shot glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e20e06f62c1c66972c39b3', 2, 'Then take an upside down spoon and touch it to the inside wall of the glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e20e06f62c1c66972c39b3', 3, 'Carefully add the Kahlua');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e20e06f62c1c66972c39b3', 4, 'Repeat this process for the Sambuca');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e20e06f62c1c66972c39b3', 5, 'If done properly, the alcohol will stay separated and resemble a bumble bee');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e20e06f62c1c66972c39b3', 6, 'Enjoy!!!');
