INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e911e6cc09589d9fc0d1a3', 1, 'Lassi is one of the easiest things to make, and there are many ways of making it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e911e6cc09589d9fc0d1a3', 2, 'Basically, it is buttermilk (yoghurt whisked with water), and you can choose almost any consistency that you like, from the thinnest to the thickest');
