INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_658c1602082530d4329ab3', 1, 'Honey', 'honey', 0, 'unsweetened', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_658c1602082530d4329ab3', 2, 'Cocoa powder', 'cocoa powder', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 0, 'Brew espresso');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 1, 'In a coffee mug, place 1 teaspoon of unsweetened powdered cocoa, then cover a teaspoon with honey and drizzle it into the cup');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 2, 'Stir while the coffee brews, this is the fun part');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 3, 'The cocoa seems to coat the honey without mixing, so you get a dusty, sticky mass that looks as though it will never mix');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 4, 'Then all at once, presto!');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 5, 'It looks like dark chocolate sauce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 6, 'Pour hot espresso over the honey, stirring to dissolve');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_658c1602082530d4329ab3', 7, 'Serve with cream');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_afc3b14d5a1ef983aeeaab', 'Mojito', 'cocktail', 'IBA Contemporary Classics — Cocktail — served in a highball glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/metwgh1606770327.jpg', 'cocktail', 0, 1, 1910, 'TheCocktailDB', 'Havana, Cuba', NULL, 'Descended from the 16th-century El Draque - a mint, lime, and aguardiente remedy linked to Francis Drake''s crew - the modern Mojito emerged in Havana around 1910 once Bacardi''s light rum replaced rougher spirits. La Bodeguita del Medio and Hemingway''s endorsement propelled it to global fame. It is Cuba''s definitive highball.', NULL, NULL, NULL, 'highball', 'built', 'mint', NULL, 'unreviewed');
