INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_4df0b30c2602166781af72', 'Mimosa', 'cocktail', 'IBA Contemporary Classics — Ordinary Drink — served in a champagne flute', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/juhcuu1504370685.jpg', 'cocktail', 0, 1, 1925, 'TheCocktailDB', 'Paris, France', NULL, 'Credited to bartender Frank Meier at the Ritz Paris in 1925, mixing equal parts Champagne and orange juice. The drink takes its name from the yellow mimosa flower. A similar Buck''s Fizz was served at London''s Buck''s Club in 1921.', NULL, NULL, NULL, 'flute', 'built', NULL, NULL, 'unreviewed');
