INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_8994777e2e30abd17393c2', 'Mai Tai', 'cocktail', 'IBA Contemporary Classics — Ordinary Drink — served in a collins glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/twyrrp1439907470.jpg', 'cocktail', 0, 1, 1944, 'TheCocktailDB', 'Oakland, USA', NULL, 'Created by Victor Bergeron at Trader Vic''s in Oakland in 1944, reportedly for Tahitian friends who exclaimed Mai Tai-Roa Ae - out of this world. Its blend of aged Jamaican rum, orange curacao, orgeat, and lime defined the mid-century tiki movement. Don the Beachcomber disputed authorship, fueling tiki''s most famous feud.', NULL, NULL, NULL, 'collins', 'shaken', 'cherry', 12, 'unreviewed');
