INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_56b9cf0d23505edb66fb89', 'Martini', 'cocktail', 'IBA Unforgettables — Cocktail — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/71t8581504353095.jpg', 'cocktail', 0, 1, 1887, 'TheCocktailDB', 'California/New York, USA', NULL, 'The Martini''s lineage traces to the Martinez, served in 1880s Northern California, and was codified in Jerry Thomas''s 1887 Bar-Tender''s Guide. As vermouth ratios dropped through the early 20th century, it evolved from sweet and aromatic to the bone-dry gin icon of the mid-century. It became the definitive American cocktail of power and sophistication.', NULL, NULL, NULL, 'coupe', 'stirred', 'olive', 26, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_56b9cf0d23505edb66fb89', 0, 'Gin', 'gin', 1.6666666666666665, 'oz', 'bar');
