INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_56b9cf0d23505edb66fb89', 1, 'Stir well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_56b9cf0d23505edb66fb89', 2, 'Strain in chilled martini cocktail glass');
