INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_eedd90dc3a30e7b441d7ec', 'Manhattan', 'cocktail', 'IBA Unforgettables — Cocktail — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/yk70e31606771240.jpg', 'cocktail', 0, 1, 1874, 'TheCocktailDB', 'New York City, USA', NULL, 'Popularized at New York''s Manhattan Club in the mid-1870s, the drink paired American rye whiskey with Italian sweet vermouth and aromatic bitters. It helped launch the vermouth craze in America and became the template for the Martini and countless variations. The Waldorf''s Old Waldorf-Astoria Bar Book later cemented its classic 2:1 ratio.', NULL, NULL, NULL, 'coupe', 'stirred', 'orange peel', 28, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_eedd90dc3a30e7b441d7ec', 0, 'Sweet Vermouth', 'sweet vermouth', 0.75, 'oz', 'bar');
