INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_eedd90dc3a30e7b441d7ec', 0, 'Stirred over ice, strained into a chilled glass, garnished, and served up');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_58c9c663d753062d59e789', 'Margarita', 'cocktail', 'IBA Contemporary Classics — Ordinary Drink — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/5noda61589575158.jpg', 'cocktail', 0, 1, 1938, 'TheCocktailDB', 'Mexico/US border', NULL, 'Multiple origin tales exist, but the most cited credits Carlos Herrera at Rancho La Gloria near Tijuana in 1938 for dancer Marjorie King, who was allergic to all spirits but tequila. The tequila-lime-orange liqueur formula mirrors the older Daisy template, from which its name may derive. It is now the best-selling cocktail in the United States.', NULL, NULL, NULL, 'coupe', 'shaken', NULL, 18, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_58c9c663d753062d59e789', 0, 'Tequila', 'tequila', 1.5, 'oz', 'bar');
