INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fa4f913222484fb2b443c3', 0, '1 - Pour the Ricard (or pastis)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fa4f913222484fb2b443c3', 1, '2 - Pour the orgeat syrup');
