INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2325e7079eb5d8c474e632', 0, 'Squeeze the juice from 1½ limes and blend with the mango to give a smooth purée');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2325e7079eb5d8c474e632', 1, 'Cut the rest of the limes into quarters, and then cut each wedge in half again');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2325e7079eb5d8c474e632', 2, 'Put 2 pieces of lime in a highball glass for each person and add 1 teaspoon of caster sugar and 5-6 mint leaves to each glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2325e7079eb5d8c474e632', 3, 'Squish everything together with a muddler or the end of a rolling pin to release all the flavours from the lime and mint');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2325e7079eb5d8c474e632', 4, 'Divide the mango purée between the glasses and add 30ml white rum and a handful of crushed ice to each one, stirring well to mix everything together');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2325e7079eb5d8c474e632', 5, 'Top up with soda water to serve and garnish with extra mint, if you like');
