INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_48fd6dbfd3279285bcb238', 'Mary Pickford', 'cocktail', 'IBA Unforgettables — Cocktail — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/f9erqb1504350557.jpg', 'cocktail', 0, 1, 1922, 'TheCocktailDB', 'Havana, Cuba', NULL, 'Invented during Prohibition at the Hotel Nacional in Havana and named for silent-film star Mary Pickford, who vacationed in Cuba with Douglas Fairbanks and Charlie Chaplin. Rum, pineapple, grenadine, and maraschino create a pink tropical sour. It symbolizes the American celebrity exodus to Cuba during the dry years.', NULL, NULL, NULL, 'coupe', 'shaken', 'maraschino cherry', 18, 'unreviewed');
