INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0ad24e39c90a2eb9d6d55c', 0, '1) Add the Bombay Sapphire, Blue Curacao, rosemary sprig and gently squeezed lemon wedge to a balloon glass');
