INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_558f3edb115cbe7074440b', 'Ramos Gin Fizz', 'cocktail', 'Cocktail — served in a highball glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/967t911643844053.jpg', 'cocktail', 0, 1, 1888, 'TheCocktailDB', 'New Orleans, USA', NULL, 'Invented by Henry C. Ramos at his Imperial Cabinet Saloon in New Orleans in 1888, requiring a notoriously long 12-minute shake to emulsify cream, egg white, and orange flower water. During Mardi Gras, Ramos employed dozens of shaker boys working in relay. Governor Huey Long famously flew a New Orleans bartender to New York to teach it.', NULL, NULL, NULL, 'highball', 'shaken', NULL, 9, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 0, 'Gin', 'gin', 1.53, 'oz', 'bar');
