INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 3, 'Cream', 'cream', 2.04, 'oz', 'dairy');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_558f3edb115cbe7074440b', 4, 'Egg White', 'egg white', 1, 'piece', 'dairy');
