INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6fe2e9d0b6227b37912e6f', 'Sidecar', 'cocktail', 'IBA Unforgettables — Ordinary Drink — served in a cocktail glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/x72sik1606854964.jpg', 'cocktail', 0, 1, 1922, 'TheCocktailDB', 'Paris/London', NULL, 'Popularized in the early 1920s at Harry''s Bar in Paris and Ciro''s in London, reportedly named for an army captain who arrived at the bar in a motorcycle sidecar. Cognac, orange liqueur, and lemon form the model for the entire sour-with-liqueur family. It appeared in print in 1922 in MacElhone''s ABC of Mixing Cocktails.', NULL, NULL, NULL, 'coupe', 'shaken', NULL, 21, 'unreviewed');
