INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_356da496ab69eeadd777ff', 0, 'Gently warm 60g golden caster sugar in a pan with 30ml water and 1 tbsp allspice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_356da496ab69eeadd777ff', 1, 'Cook gently until the sugar has dissolved, then leave the mixture to cool');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_356da496ab69eeadd777ff', 2, 'Strain through a sieve lined with a coffee filter (or a double layer of kitchen paper)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_356da496ab69eeadd777ff', 3, 'Pour 60ml of the spiced syrup into a cocktail shaker along with 200ml rum and 90ml lime juice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_356da496ab69eeadd777ff', 4, 'Shake with ice and strain between six flute glasses');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_356da496ab69eeadd777ff', 5, 'Top up with 600ml champagne and garnish each with an orange twist');
