INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_628425347a17d7e2aa7f76', 3, 'Lime Juice', 'lime juice', 0.51, 'oz', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_628425347a17d7e2aa7f76', 4, 'Sugar Syrup', 'sugar syrup', 1, 'dash', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_628425347a17d7e2aa7f76', 5, 'Salt', 'salt', 1, 'pinch', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_628425347a17d7e2aa7f76', 0, 'Vampiros may be made in a tall glass or an old fashioned glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_628425347a17d7e2aa7f76', 1, 'Bartenders may first "rim" the glass with Kosher Salt, which is done by placing a layer of Kosher Salt on a chopping board, moistening the glass'' rim with lime juice or water, and then placing the upside down glass rim onto the Kosher Salt, so that the salt sticks to the moistened rim');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_628425347a17d7e2aa7f76', 2, 'The second step is to fill half the glass with ice and add one or two shooter glasses full of high quality Tequila');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_628425347a17d7e2aa7f76', 3, 'The next stage is to add the flavouring elements');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_628425347a17d7e2aa7f76', 4, 'This is done by squeezing a fresh lime into the glass, adding a few grains of salt, adding citrus-flavoured soda pop, until the glass is 4/5 full, and then adding spicy Viuda de Sanchez (or orange juice, lime juice and pico de gallo)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_628425347a17d7e2aa7f76', 5, 'The final step is to stir the ingredients so that the flavours are properly blended');
