INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_687cee4a84235f6d26fdb6', 'White Russian', 'cocktail', 'Ordinary Drink — served in a old-fashioned glass', 1, 3, 0, 'https://www.thecocktaildb.com/images/media/drink/vsrupw1472405732.jpg', 'cocktail', 0, 1, 1965, 'TheCocktailDB', 'Belgium/USA', NULL, 'A cream-added variant of the Black Russian first documented in Oakland Tribune in 1965. Vodka, coffee liqueur, and cream gained its enduring fame from The Big Lebowski in 1998, where the Dude made it his signature. Sales of Kahlua reportedly doubled after the film.', NULL, NULL, NULL, 'rocks', 'built', NULL, 26, 'unreviewed');
