INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1692cc9e9860ac72254933', 0, 'Everyone’s favourite Paloma gets a delicious Indian makeover');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1692cc9e9860ac72254933', 1, 'Tequila reposado infused with “Timur Pepper” which has citrusy & grapefruit notes and is grown at the foothills of Himalaya');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1692cc9e9860ac72254933', 2, 'It also produces a slightly numbing and tingling sensation on your lip when consumed');
