INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_cf78a4f8abdf7344d72411', 'Absinthe Dripped', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'ABSINTHE   DRIPPED
1    pony    of   Absinthe.
Fill  the  bowl  of  your  absinthe  glass  (which  has  a  hole
in  the  center)  with  fine  ice  and  the  balance  with  water.
Then  elevate  the  bowl  and  let  contents  drip  into  the  glass
containing  the  absinthe  until  the  color  shows  a  sufficiency.
Pour  into   a   thin  bar  glass  and  serve.', NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
