INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5688da40f10f9060d2bdcd', 'Bowl Of Egg Nogg', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'BOWL  OF  EGG   NOGG
(For  parties.)
i  lb.  of  sugar
10  eggs.     Yolks  should  be  separated.     Beat  yolks  with   sugar
until  dissolved.
Pour  in   I   pt.   Martell  brandy
i   wine-glass   of  Jamaica   rum
3  qts.   of  rich   milk.
Mix  ingredients  well  with  a  ladle  and  stir  continually
while  pouring  in  milk,  to  prevent  from  curdling.  Then  beat
whites  of  eggs  and  put  on  top  of  mixture.     Serve.', NULL, NULL, 'wine', 'stirred', NULL, NULL, 'unreviewed');
