INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_613ab6abe1f7388254429b', 'Lemonade', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'LEMONADE
(Use   large  bar   glass,   half   full   of   ice.)
1    heaping    tablespoonful   of  sugar
6  or  8  dashes  of  lemon  juice.
Fill  up  with  water,  shake  well,  dress  with  fruits,  serve
with  straw.  When  customer  wishes  lemonade  strained,  put
into  smaller  glass  and  place  slice  of  orange  in  glass.
An  Angostura  Lemonade  is  made  like  the  foregoing  with
the   addition   of   1   teaspoonful   Angostura    bitters.', NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
