INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_75c7a8a03029d1f94bf842', 'Nicholas Cocktail', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'NICHOLAS  COCKTAIL
50%    orange    gin
50%   sloe  gin
Fill  glass  with  ice.
Stir,  strain  and  serve.
"ONE   YARD   OF   FLANNEL"  or  "ALE    FLIP"
Put  a  quart  of  Bass  &  Co.''s  Barley  Wine,  or  Strong
Ale,  on  the  fire  to  warm,  and  beat  up  three  or  four  eggs
with  four  ounces  of  moist  sugar,  a  teaspoonful  of  grated  nut-
meg or  ginger  and  a  quarter  of  good  old  rum  or  brandy.
When  the  ale  is  near  to  a  boil  put  into  one  pitcher,  and  the
rum  and  eggs,  etc.,  into  another;  turn  it  from  one  pitcher  till
it  is  smooth  as  cream.', NULL, NULL, NULL, 'stirred', NULL, NULL, 'unreviewed');
