INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_35c8e4986f26763099ae64', 'Turkish Sherbet', 'cocktail', NULL, 1, 3, 0, NULL, 'cocktail', 1, 1, 1908, 'Jack''s Manual (J.A. Grohusko, 1908)', 'New York, USA', NULL, NULL, 'TURKISH  SHERBET
(Use  a  punch  bowl.)
Mix  as  follows:
2  quarts    of   sweet    wine
2  quarts  of  water
4  pounds  of  sugar
y2  wineglass  of  Angostura  bitters
4  lemons,  juice  only
6  oranges,  juice  only
t   pound   blanched  almonds
1   pound  Muscatel  grapes
\  pound  figs,  cut  up
\  pound   seedless  raisins
1  1-3  dozen  eggs,  whites  only
i    dozen   cloves,  a   small   piece   cinnamon   and   a   little   caramel
coloring.
Make    a    hot    syrup    of   the    sugar    and    water   and    pour    it
over  the  raisins,  cloves  and  cinnamon.
When     cool,     add     orange    and     lemon     juice     and     wine.
Strain   and  freeze  in    the  usual   manner.
Take    out    the    spices    and    add    the    scalded    raisins,    figs,
grapes  and  almonds  last.', NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
