INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_04075d4a53ae8520f35b8f', 2, 'pineapple juice', 'pineapple juice', 3.5, 'cl', 'produce');
