INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6bdd7eee89e8dc163addc1', 1, 'Reduce heat, cover and simmer 20  minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6bdd7eee89e8dc163addc1', 2, 'Add teabags and milk, simmer 3-5 minutes.');
