INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_74c0a40f66fde1af0e98d7', 'Chicha Peruana', 'beverages', 'Chicha (corn beer). Chicha is made in South and, to a lesser extent, Central America. Unlike African opaque beer, it is not brewed commercially, but instead is made and served in what sound to me like wee tiny brewpubs. An abbreviated version is also made in people''s kitchens. Chicha is consumed whilst still fermenting and so is low in alcohol. It is often spiced and may also be served with fruit.  With Bill''s help and a little patience, a friend and I recently completed a batch. This was a very interesting and satisfying endeavour which included growing and malting the corn used. Every step of the process was very simple, and I highly recommend attempting this at home. My second crop of corn is about to come in and the results were good enough that I will be doing this again in the near future.', 1, 165, 110, 'character(0)', 'drink', 0, 0, NULL, 'HuggingFace: AkashPS11/recipes_data_food.com', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_74c0a40f66fde1af0e98d7', 0, 'piloncillo cone', 'piloncillo cone', 1.5, NULL, 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_74c0a40f66fde1af0e98d7', 1, 'Nottingham dry yeast', 'nottingham dry yeast', 1, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 0, 'Procedure: Mash for 90 minutes at 160°F.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 1, 'We did two 1.5 gallon batches, each spiced differently (one with curacao/coriander, the other with allspice/cinammon). We would rather have used a higher proportion of jora, but on brewday we discovered that our ability to determine the weight of things is seriously imparied.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 2, 'Instead of the 4.5lbs we thought we had, we found we had only 3lbs of jora.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 3, 'Rather than readjust (the OG would have been more appropriate at ~1.045 in any case), we added more sugar, a course of action that was inspired by homebrewed Weizen as much as anything else. The result is a very tasty beverage, pretty big all the way around on corn, and yet the flavor is quite subtle. Be warned that chicha is at its peak 2 to 4 days after pitching while it still retains some sweetness and body.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 4, 'Once the chicha ferments out, you are left with a fairly bland beverage that reminds me of iced tea more than anything else. If I''d been thinking (chicha lends itself to gulping), I would have kegged the stuff on the third day after pitching and stuck it in the fridge. While we took the trouble to grow our own (blue) corn, I see no reason why one could not start with good ol'' yellow corn from the grocery store (domestic 20-row?) In fact, I plan on doing this if only to see what kind of chicha it makes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 5, 'Specifics:  OG: 1.055  FG: 1.012 Types of Chicha So far, there appear to me to be several main ways in which chicha de jora is made. These range in difficulty from trivial to a process almost indentical to what barley-beer homebrewers are familiar with.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 6, 'Facil (easy) - Corn is mixed with water and sugar and allowed to sit for several days until the corn begins to germinate. The sugar ferments and the corn, lending nothing fermentable, adds flavor.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 7, 'Abbreviated - The jora is mashed but the mash is ultimately brought to a boil, allowed to settle, and the clear liquid, or upi, now finished chicha, is drawn off.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 8, 'Traditional - Similiar to the Abbreviated method, but the jora is mashed and the mash is allowed to settle. The upi is drawn off the mash into a separate vessel for boiling.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 9, 'Modern - The ground jora is mashed and lautered through some sort of filtering device such as a manifold or false bottom.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 10, 'This process is helped by the inclusion of some crushed malted barley (Barley Assisted). The first is apparently how much chicha is made in people''s kitchens.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 11, 'Bill Ridgely describes most of the others in his articles.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 12, 'Also note that the methods that include mashing use a batch sparge. That is, the sweet liquor (upi) is merely drained from the mash and there are no continuous additions of sparge water to the surface of the mash.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 13, 'Certainly sparging can be performed if desired, but it is neither traditional nor necessary (corn kernels have no husk and therefore do not form a filterbed). Chicha is traditionally allowed to spontaneously ferment. For the last type (Modern), George Duarte suggests that ground, unmalted corn could be mixed with a small amount of crushed 2-row malted barley and boiled for 20 minutes or so to gelatinize the starch in the corn.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 14, 'This gooey mass would then be added to more water and barley malt and mashed as per ''normal'' homebrew procedures.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_74c0a40f66fde1af0e98d7', 15, 'This could probably be sparged as usual.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_16dd4c6fcde4eca7246a82', 'Christmas Snow Punch', 'punch beverage', 'Here is a punch recipe that we used at my in-laws 50th Anniversary open house.  CHRISTMAS SNOW PUNCH', 32, 15, 0, 'character(0)', 'drink', 0, 0, NULL, 'HuggingFace: AkashPS11/recipes_data_food.com', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
