INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_444758cb39e07b119da893', 4, 'Monarch 151 rum', 'monarch 151 rum', 1, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_444758cb39e07b119da893', 0, 'Bring to boil water and sugar.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_444758cb39e07b119da893', 1, 'Remove from heat and add instant');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_444758cb39e07b119da893', 2, 'coffee. Bring to boil again.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_444758cb39e07b119da893', 3, 'Remove from heat and add vanilla extract   (very important you use pure extract NOT imitation). Cool before   adding rum.');
