INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 0, 'Do not wash the flower, but remove any insects and the thick stalks.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 1, 'Place the  sugar in a very large bowl and cover with 2 pints of boiling water.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 2, 'Stir until  the sugar has dissolved.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 3, 'Then add 6 pints cold water, the rind and juice of the  lemons, the vinegar and flowers.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 4, 'Stir well.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 5, 'Cover and leave, covered, for 48  hours, stirring occasionally.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 6, 'Strain through a fine sieve into clean bottles  with screw tops.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 7, 'Leave an inch gap at the top of each bottle and screw down  well.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_6aeef122ff874e165f0209', 8, 'Leave in a cool place to mature. Nice served with ice. Ready to drink in 6 weeks but it tastes better the longer it is left.');
