INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 0, 'Heat water, brown sugar, chocolate, cloves, and cinnamon to boiling in  3-quart saucepan; reduce heat. Simmer, uncovered, for 15 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 1, 'Stir  in coffee. Remove from heat; cover and let stand 5 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 2, 'Stir in  vanilla.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 3, 'Strain coffee through 4 thicknesses of cheesecloth.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 4, 'Keep hot in saucepan after straining.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 5, 'Heat brandy  just until warm in small, long-handled saucepan.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 6, 'Remove from heat;  ignite. Pour flaming brandy over coffee. Allow flame to burn out; stir.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 7, 'Pour coffee into cups or mugs.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 8, 'Top each with whipped cream and 1 Tbsp  liqueur.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_70bfc4a6264b758849023a', 9, 'Garnish with cinnamon stick, if desired.');
