INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b4673f7aca9eb97cf5ab0b', 6, 'sour mix', 'sour mix', 1, 'tablespoon', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b4673f7aca9eb97cf5ab0b', 0, 'Combine tequila, vodka, rum, gin, and raspberry liqueur in a highball glass. Fill with ice and top with sour mix.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_101823891fbba5e79148a0', 'Hot and Sweet Ginger Drink', 'drink', 'This Chinese-inspired sweet ginger tea recipe is deceptively simple but hard to resist. It''s a great substitute for hot spiced apple cider during the holidays, and it warms the soul on a cold winter evening!', 5, 5, 10, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_101823891fbba5e79148a0', 0, 'water', 'water', 5, 'cups', 'drinks');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_101823891fbba5e79148a0', 1, 'sliced fresh ginger', 'sliced fresh ginger', 0, 'cup', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_101823891fbba5e79148a0', 2, 'packed brown sugar', 'packed brown sugar', 1, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_101823891fbba5e79148a0', 3, 'honey', 'honey', 1, 'tablespoon', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101823891fbba5e79148a0', 0, 'Bring water and ginger to a boil in a saucepan, then reduce the heat to medium-low and simmer for 5 minutes.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_101823891fbba5e79148a0', 1, 'Add brown sugar and honey and stir until sugar dissolves. Strain out ginger and serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_18e8d72d7ab5e8be335ec0', 'Mango Lemonade', 'drink', 'Mango lemonade is the perfect drink when it''s hot outside. It''s simple, beautiful to look at, and delicious. That''s why I love to make this mango lemonade all summer long!', 4, 10, 5, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
