INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_18e8d72d7ab5e8be335ec0', 2, 'chopped mango', 'chopped mango', 2, 'cups', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_18e8d72d7ab5e8be335ec0', 3, 'water', 'water', 1, 'cup', 'drinks');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_18e8d72d7ab5e8be335ec0', 4, 'lemon juice', 'lemon juice', 1, 'cup', 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_18e8d72d7ab5e8be335ec0', 5, 'ice', 'ice', 2, 'cups', 'drinks');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18e8d72d7ab5e8be335ec0', 0, 'To make the simple syrup: Combine sugar and water in a saucepan over medium-high heat. Bring to a boil and stir until sugar has dissolved. Remove from heat and allow to cool.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18e8d72d7ab5e8be335ec0', 1, 'To make the mango lemonade: Combine mango and 1 cup water in a blender or food processor until smooth. Pour mango through a strainer into a pitcher. Stir in lemon juice and simple syrup. Mix well.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_18e8d72d7ab5e8be335ec0', 2, 'Add ice to the pitcher and serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_ef9125af9869e956176701', 'Homemade Blackberry Lemonade', 'drink', 'This homemade lemonade is easy to make and gets a flavor boost from blackberries. The end result is light and refreshing which is perfect for those hot summer days.', 4, 5, 5, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
