INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_61ef999dfccce9d45e3a0e', 2, 'When gelatin is cool, pour into a large punch bowl. Stir in pineapple juice, orange juice concentrate, sugar, and 4 ½  cups cold water.');
