INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2f04c9086059e6e7749eaa', 1, 'Pour in tequila and triple sec, then add strawberries and limeade concentrate.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2f04c9086059e6e7749eaa', 2, 'Blend until smooth, about 30 seconds. Pour into four margarita glasses and serve immediately.');
