INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_62b0d27ce8ab01d48f6323', 0, 'Place watermelon into a blender; cover and puree until smooth. Strain through a fine mesh sieve.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_62b0d27ce8ab01d48f6323', 1, 'Bring sugar and 1/2 cup water to a boil in a saucepan over medium-high heat until sugar dissolves, about 5 minutes. Remove from heat; stir in 3 cups of cold water and lemon juice.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_62b0d27ce8ab01d48f6323', 2, 'Divide ice into 12 glasses; scoop 2 to 3 tablespoons of watermelon puree over ice, then top with lemonade. Gently stir before serving.');
