INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2fc8bdb84a943211d14368', 0, 'Gather all ingredients.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2fc8bdb84a943211d14368', 1, 'Mix red wine, brandy, triple sec, lemonade concentrate, orange juice, lemon juice, and sugar together in a bowl. Add orange, lemon and lime slices, and maraschino cherries.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2fc8bdb84a943211d14368', 2, 'Serve immediately over ice, or refrigerate 8 hours to overnight for best flavor. For a fizzy sangria, add club soda just before serving.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_48624ee04831b5d66f7b98', 'Spicy Mezcal Margarita', 'drink', 'This mezcal margarita is made with smoky mezcal tequila flavored with jalapeño, orange juice, and lime for a delicious spicy margarita cocktail.', 2, 15, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
