INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_48624ee04831b5d66f7b98', 0, 'Mix 1 tablespoon sugar with salt on a shallow, rimmed plate. Use lime wedge to wet rims of two 8-ounce glasses. Dip rims into sugar mixture.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_48624ee04831b5d66f7b98', 1, 'Combine jalapeño and 1 1/2 teaspoons sugar in a cocktail shaker and muddle until sugar is dissolved and jalapeño is juiced. Add orange juice, mezcal, and lime juice to shaker, then fill with ice. Cover and shake until chilled, about 30 seconds. Strain into glasses to serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_978d408ed430742ffbb3c7', 'Watermelon Sangria', 'drink', 'This watermelon sangria is one of my favorite summer recipes. If you love watermelon and white wine, you''ll love this fruity drink on a hot day!', 16, 20, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
