INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_978d408ed430742ffbb3c7', 0, 'Place 9 cups of watermelon cubes in a blender; blend on high until very smooth. Strain juice through a mesh strainer into a large pitcher.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_978d408ed430742ffbb3c7', 1, 'Pour wine, vodka, triple sec, and simple syrup into the pitcher; stir to combine. Add remaining 3 cups of watermelon cubes, orange sections, blueberries, and lime quarters; chill sangria for 4 hours before serving.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_fc2714782c5d75350b5b95', 'Strawberry Lassi', 'drink', 'This delicious strawberry lassi is easy to make in the summer with ripe strawberries for a refreshing creamy drink or light dessert. Sprinkle some ground cardamom on top if you like.', 3, 10, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
