INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc2714782c5d75350b5b95', 0, 'Cut 3 strawberries into small pieces and set aside. Place remaining strawberries and sugar into a blender; blend on high speed for 30 seconds. Pour in milk and blend another 30 seconds. Add yogurt and blend on high speed for 1 minute.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc2714782c5d75350b5b95', 1, 'Place 1 ice cube in each of 3 glasses and pour in lassi. Top with reserved strawberry pieces and serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_b80a7d67c5f7df75bdf489', 'Cucumber Jalapeño Margarita', 'drink', 'This cucumber jalapeño margarita is so refreshing! Nothing tastes better than the combination of tequila and jalapeño — the cucumber just adds a freshness and helps to balance the heat. The longer it chills, the more jalapeño and cucumber infuses into the tequila. Serve over ice in a salt-rimmed glass, garnished with cucumber slices.', 4, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
