INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1d2e634c9a1aa31323bf47', 0, 'Combine dark rum, light rum, lime juice, and passion fruit syrup in a cocktail shaker. Add ice; cover and shake until the outside of the shaker has frosted. Strain into a chilled glass.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d5f9e28f0b9de8ff7151a5', 'Black Russian Cocktail', 'drink', 'If you''ve ever wondered how to make a black Russian cocktail, it''s easy! Just combine vodka (the quintessential Russian spirit) with the dark coffee-flavored liqueur (Kahlua).', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
