INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d5f9e28f0b9de8ff7151a5', 1, 'coffee-flavored liqueur (such as Kahlua®)', 'coffee-flavored liqueur such as kahlua', 0, 'fluid ounce', 'bar');
