INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d5f9e28f0b9de8ff7151a5', 0, 'Combine vodka and coffee liqueur in a rocks glass. Add ice and stir to combine.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_8db519b9970d4286839120', 'Earl Grey Martini', 'drink', 'This ''martini'' is perfect for fans of Earl Grey tea!', 2, 10, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
