INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8db519b9970d4286839120', 0, 'Sprinkle the tea leaves over the gin in a small glass, and set aside to steep for 2 hours.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8db519b9970d4286839120', 1, 'Pour 1/4 to 1/2 inch of white sugar onto a small, shallow plate. Moisten the rims of 2 martini glasses with a wedge of lemon, dip the moistened glasses into the sugar; set aside.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8db519b9970d4286839120', 2, 'Strain the infused gin, lemon juice, and simple syrup into a cocktail shaker over ice. Cover, and shake until the outside of the shaker has frosted. Strain into the rimmed glasses to serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6d5889d290d3e879e38d32', 'Blueberry Lemonade', 'drink', 'This tasty blueberry lemonade is so refreshing on a hot day! It''s easy to make from scratch by blending fresh blueberries with lemon juice, your favorite sweetener, and water.', 12, 15, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
