INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_625bfc9f3c8a5630bcdfe0', 0, 'Combine strawberries, tequila, orange-flavored liqueur, lemon juice, sugar, and basil leaves in a blender; mix on low until smooth. Add ice and puree until ice is crushed, 30 to 60 seconds.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_52c9a64f2ca205f1e4db34', 'Baby Blue Punch', 'drink', 'I made this baby shower punch when I knew I was having a boy. The ice cream melts somewhat and turns the punch a beautiful baby blue color leaving frothy blue and white clouds floating on top. Try any flavor or color of unsweetened drink mix in place of the blue. The sky''s the limit!', 24, 10, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
