INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10b6741cc638e633bdb4fc', 0, 'Cut strawberries in half and watermelon into chunks, or use a melon baller.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10b6741cc638e633bdb4fc', 1, 'Combine strawberries, watermelon, and raspberries in a large bowl. Pour rosé, vermouth, and honey into a large pitcher and stir until honey dissolves. Add 1/2 of the fruit and basil. Place pitcher and remaining fruit in a refrigerator for at least 6 hours.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10b6741cc638e633bdb4fc', 2, 'Scoop a large spoonful of cold fruit into the bottom of glasses; add sangria and sparkling cucumber water to taste.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_869b0753ec45e27386127f', 'Apple Banana Smoothie', 'drink', 'This apple and banana smoothie is a thick, healthy fruit drink with apple, banana, and orange juice. The frozen banana takes the place of shaved ice and results in a smooth, creamy texture. Serve with a dollop of whipped cream for added effect.', 2, 5, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
