INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_24eb44cc14e78b4e83b9c0', 'Berries and Cream Smoothie', 'drink', 'If you have ever had a bowl of berries mixed with a little sugar and then topped with some whipping cream, you know that it is heavenly. If you haven''t tried it before, maybe you shouldn''t so that you can avoid forming an addiction. Whether you''ve had it or not, here is a great recipe that tastes just like it. It is simply in the on-the-go, drinkable form. Garnish with whipped cream and/or berries.', 3, 5, 0, NULL, 'drink', 0, 0, NULL, 'HuggingFace: AWeirdDev/all-recipes-sm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
