INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_e08c59f0e87fc2075b73b5', 'Oxford Punch', 'cocktail', 'A 19th-century punch-style drink from Jerry Thomas''s 1862 Bartenders Guide.', 8, 5, 0, NULL, 'cocktail', 1, 1, 1862, 'The Bon-Vivant''s Companion (Jerry Thomas, 1862)', 'New York, USA', NULL, NULL, '63. Oxford Punch. 

We have been favored by an English gentleman with 
the following reeipe for the concoction of punch as drunk 
by the students of the University of Oxford : 

Rub the rinds of three fresh lemons with loaf-sugar till 
you have extracted a portion of the juice; cut the peel 
finely off two lemons more, and two sweet oranges. Use 
the juice of six lemons, and four sweet oranges. Add six 
glasses of calf ''s-foot jeDy ; let all be put into a large jug, 
and stir well together. Pour in two quarts of water boil- 
ing hot, and set the jug upon the hob for twenty minutes. 
Strain the liquor through a fine sieve into a large bowl ; 
pour in a bottle of capillaire,* half a pint of sherry, a pint 
of Cognac brandy, a pint of old Jamaica rum, and a quart 
of orange shrub ; stir well as you pour in the spirit. If 
you find it requires more sweetness, add sugar to your 
taste.', NULL, NULL, 'rocks', 'stirred', NULL, 14, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_e08c59f0e87fc2075b73b5', 0, 'juice of lemons, and four sweet oranges. add six', 'juice of lemons and four sweet oranges add six', 6, 'piece', 'produce');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e08c59f0e87fc2075b73b5', 0, 'We have been favored by an English gentleman with the following reeipe for the concoction of punch as drunk by the students of the University of Oxford : Rub the rinds of three fresh lemons with loaf-sugar till you have extracted a portion of the juice; cut the peel finely off two lemons more, and two sweet oranges.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e08c59f0e87fc2075b73b5', 1, 'Use glasses of calf ''s-foot jeDy ; let all be put into a large jug, and stir well together.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_e08c59f0e87fc2075b73b5', 2, 'Pour in two quarts of water boil- ing hot, and set the jug upon the hob for twenty minutes.');
