INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_a8eb77c837f82d970839ae', 0, 'Dissolve the sugar with a little water ; break the yolk of the egg in a large glass ; put in one-quarter tumblerful of broken ice ; fill with milk, and shake up until the egg is thoroughly mixed with the other ingredients, then grate ! a little nutmeg on top, and quaff the nectar cup.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_59e4c419cf8a98efeef20b', 'Mint Julep', 'cocktail', 'A 19th-century julep-style drink from Jerry Thomas''s 1862 Bartenders Guide.', 1, 5, 0, NULL, 'cocktail', 1, 1, 1862, 'The Bon-Vivant''s Companion (Jerry Thomas, 1862)', 'New York, USA', NULL, 'Rooted in 18th-century Virginia as a morning medicinal, the julep entered print in 1803 and was defined with bourbon, sugar, and mint by the 1830s. Senator Henry Clay helped popularize it in Washington, and Churchill Downs made it the official drink of the Kentucky Derby in 1938. It is the South''s most storied cocktail.', '88. Mint Julep. 

% 

(Use large bar glass.) 

1 table-spoonful of white pulverized sugar. 

2£ do. water, mix well with a spoon. 

Take three or four sprigs of fresh mint, and press them 
well in the sugar arid water, until the flavor of the mint is 
extracted ; add one and a half wine-glass of Cognac bran- 
dy, and fill the glass with fine shaved ice, then draw out 
the sprigs of mint and insert them in the ice with the 
stems downward, so that the leaves will be above, in the 
shape of a bouquet ; arrange berries, and small pieces of 
sliced orange on top in a tasty manner, dash with Jamaica 
rum, and sprinkle white sugar on top. Place a straw as 
represented in the cut, and you have a julep that is fit for 
an emperor.', NULL, NULL, 'collins', 'built', 'mint', 14, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_59e4c419cf8a98efeef20b', 0, 'table-spoonful of white pulverized sugar', 'table-spoonful of white pulverized sugar', 1, 'piece', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_59e4c419cf8a98efeef20b', 1, 'water, mix well with a spoon', 'water mix well with a spoon', 2.5, 'piece', 'other');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_59e4c419cf8a98efeef20b', 0, '% Take three or four sprigs of fresh mint, and press them well in the sugar arid water, until the flavor of the mint is extracted ; add one and a half wine-glass of Cognac bran- dy, and fill the glass with fine shaved ice, then draw out the sprigs of mint and insert them in the ice with the stems downward, so that the leaves will be above, in the shape of a bouquet ; arrange berries, and small pieces of sliced orange on top in a tasty manner, dash with Jamaica rum, and sprinkle white sugar on top.');
