INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_e57d29694b6013f28999c8', 'Raspberry Shrub', 'cocktail', 'A 19th-century flip / negus / shrub-style drink from Jerry Thomas''s 1862 Bartenders Guide.', 1, 5, 0, NULL, 'cocktail', 1, 1, 1862, 'The Bon-Vivant''s Companion (Jerry Thomas, 1862)', 'New York, USA', NULL, NULL, '157. Raspberry Shrub. 

1 quart of vinegar. 

3 quarts of ripe raspberries. 

After standing a day, strain it, adding to each pint a 
pound of sugar, and skim it clear, while boiling about half 
an hour. Put a wine-glass of brandy to each pint of the 
shrub, when cool. Two spoonfuls of this mixed with a 
tumbler of water, is an excellent drink in warm weather, 
and in fevers. • 

•', NULL, NULL, 'rocks', 'built', NULL, 14, 'unreviewed');
