INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_02d980637ca6c5693a2c2a', 'White Lion', 'cocktail', 'A 19th-century fancy drink-style drink from Jerry Thomas''s 1862 Bartenders Guide.', 1, 5, 0, NULL, 'cocktail', 1, 1, 1862, 'The Bon-Vivant''s Companion (Jerry Thomas, 1862)', 'New York, USA', NULL, NULL, '176. White Lion. 

(Use small bar glass.) 

1£ teaspoonful of pulverized white sugar. 

\ a lime (squeeze out juice and put rind in glass). 

1 wine-glass Santa Cruz rum. 

\ teaspoonful of Curacoa. 

£ do. raspberry syrup. „ 

* Aromatic Rncture. — Take of ginger, cinnamon, orange peel, each 
one ounce ; valerian half an ounce, alcohol two quarts, macerate in a 
close vessel fpr fourteen days, then filter through unsized paper. 
Mix well, ornament with berries in season, and cool with 
shaved ice.', NULL, NULL, 'rocks', 'built', 'orange peel', 8, 'unreviewed');
