INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_36526ee541f04c79c19584', 'A Bishop', 'cocktail', 'A 19th-century fancy drink-style drink from Jerry Thomas''s 1862 Bartenders Guide.', 1, 5, 0, NULL, 'cocktail', 1, 1, 1862, 'The Bon-Vivant''s Companion (Jerry Thomas, 1862)', 'New York, USA', NULL, NULL, '183. A Bishop. 

(Protestant) 

4 table-spoons of white sugar, 
2 tumblers of water. 
1 lemon, in slices. 

1 bottle of claret. 

4 table-spoons of Santa Cruz or Jamaica. 

Ice. 

>', NULL, NULL, 'rocks', 'built', NULL, 14, 'unreviewed');
