INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_65328bedd6eca1047f8eda', 2, 'bitter almonds, bruised', 'bitter almonds bruised', 12, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_65328bedd6eca1047f8eda', 3, 'coriander-seeds', 'coriander-seeds', 1, 'lb', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 0, '2^ lbs. of white sugar. 86 cloves.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 1, 'Grate a sufficient number of quinces to make 2 quarts of juice, and squeeze them through a jelly-bag.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 2, 'Mix the ingredients all together, and put them in a demijohn, and shake them well every day for ten days.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 3, 'Then strain the liquid through a jelly-bag till it is perfectly clear, and bottle for use.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 4, 'This is a delightful liqueur, and can be relied upon, as it is from a recipe in the possession of a lady who is famous for concocting delicious potations. 191.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 5, 'Claret Cup, or Mulled Claret.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 6, 'Peel one lemon fine, add to it some white pounded sugar ; pour over one glass of sherry, then add a bottle of claret (vin ordinaire, the best), and sugar to taste ; add a sprig of verbena, one bottle of soda-water, and nutmeg, if you like it.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 7, 'For cup, strain and ice it well.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_65328bedd6eca1047f8eda', 8, 'For mull, heat it and serve it hot.');
