INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_39c64c2a2527d4736be82d', 0, '1 small glass of brandy. •*»* Juice of half a lemon, peel of quarter of a lemon ; sugar and nutmeg to taste ; a sprig of verbena.');
