INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_863a5e16e47f3a4e24e4e4', 'California Style Absinthe', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'A mixing-glass* half full fine ice, one jigger absinthe. Shake until very cold, strain into thin bar-glass, fill with siphon seltzer or carbonic. * By a mixing-glass is meant a large soda-glass, holding twelve ounces ; it is handier and gives better satisfaction than a goblet. A jigger is a measure used for measuring liquors when mixing drinks ; it holds two ounces. A pony holds half a jigger.', NULL, NULL, 'coupe', 'shaken', NULL, 20, 'unreviewed');
