INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_cc3496e128b8ae5af3d5d0', 'Dripped Absinthe', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, '(Use Absinthe Drip-glass.) Pour one pony of absinthe into the bottom glass, fill the upper (drip) glass full of ice-water. When two-thirds of the water has dripped into the ab- sinthe it is ready to be drunk. A few drops of anisette will improve this drink.', NULL, NULL, 'coupe', 'dripped', NULL, 20, 'unreviewed');
