INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_471ead017e513f95a8675b', 0, 'Put into a long thin glass one lump cut-loaf sugar saturated with Peyschaud or Angostura bit- ters, add one lump of ice, a small piece of lemon- peel; fill the glass three-fourths full cold cham- pagne.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_471ead017e513f95a8675b', 1, 'Stir with spoon and serve.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_602be512eb9b658bd91442', 'Chocolate Cocktail', 'cocktail', '1895 Kappeler cocktail, preserved verbatim from Modern American Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Break a fresh egg into a mixing-glass, half full fine ice, add one dash bitters, one jigger port wine, one teaspoonful fine sugar. Shake well and strain into a cocktail-glass.', NULL, 'Contains raw egg. Use pasteurized eggs or omit for food-safety.', 'coupe', 'shaken', NULL, 32, 'unreviewed');
