INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_789f7d572f38f5d5c30074', 'Brandy Crusta', 'cocktail', 'A crusta — sugared-rim fancy drink, predecessor to the sidecar.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', 'Created by Joseph Santini at the Jewel of the South in New Orleans around 1852, featuring a dramatic sugar-rimmed glass lined with a full lemon peel. Brandy, orange liqueur, lemon, and bitters made it the first cocktail to use citrus juice. It is the direct ancestor of the Sidecar and Margarita.', 'Fill a mixing-glass half full of fine ice; add three dashes of gum-syrup, two dashes mara- schino, the juice of a quarter of a lemon, two dashes Peyschaud or Angostura bitters, and one jigger brandy ; mix. Take a lemon the size of a fancy sauterne or claret glass; peel the rind from three-fourths of it all in one piece; fit it into the glass; moisten the edge of the glass with a piece of lemon, and dip it into fine sugar, which gives it a frosted appearance. Strain your mix- ture into this glass, trim with fruit, and serve.', NULL, NULL, 'coupe', 'stirred', 'seasonal fruit', 20, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_789f7d572f38f5d5c30074', 0, 'gum-syrup', 'gum-syrup', NULL, 'dashes', 'bar');
