INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_789f7d572f38f5d5c30074', 2, 'Peyschaud', 'peyschaud', NULL, 'dashes', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_789f7d572f38f5d5c30074', 3, 'brandy', 'brandy', NULL, 'jigger', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_789f7d572f38f5d5c30074', 0, 'Fill a mixing-glass half full of fine ice; add three dashes of gum-syrup, two dashes mara- schino, the juice of a quarter of a lemon, two dashes Peyschaud or Angostura bitters, and one jigger brandy ; mix.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_789f7d572f38f5d5c30074', 1, 'Take a lemon the size of a fancy sauterne or claret glass; peel the rind from three-fourths of it all in one piece; fit it into the glass; moisten the edge of the glass with a piece of lemon, and dip it into fine sugar, which gives it a frosted appearance.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_789f7d572f38f5d5c30074', 2, 'Strain your mix- ture into this glass, trim with fruit, and serve.');
