INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0a89f9a3337512fc9cc628', 0, 'Put into a glass pitcher two or three lumps of clear ice, the juice of half a lemou, one-half table- spoonful fine sugar, one pony maraschino, one pony white curagoa, one pony pale brandy, a few slices of orange, two slices of lemon, one slice cucumber-rind; pour in one quart of cold cham- pagne, one bottle of cold plain soda; mix.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0a89f9a3337512fc9cc628', 1, 'Top off with a few sprigs of fresh mint.');
