INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f56af749f0d10ebb417510', 'Claret Cup a l''Anglaise', 'cocktail', 'Pitcher/punch-bowl wine cup, ornamented with fruit and mint.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'This is a modification of the English claret cup, and shares the general fashionable rage for all things a l''Anglaise. Take twelve ounces of fine sugar, the zest of a lemon, two oranges without their seeds, pour upon this two bottles of claret and two bottles plain soda; add the small end of a cucumber not peeled (if you have borage add a lit- tle). Pour this mixture into a large bowl upon chopped ice. Serve when cold.', NULL, NULL, 'punch-bowl', 'stirred', NULL, 12, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_f56af749f0d10ebb417510', 0, 'fine sugar', 'fine sugar', NULL, 'ounce', 'bar');
