INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f56af749f0d10ebb417510', 1, 'Take twelve ounces of fine sugar, the zest of a lemon, two oranges without their seeds, pour upon this two bottles of claret and two bottles plain soda; add the small end of a cucumber not peeled (if you have borage add a lit- tle).');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f56af749f0d10ebb417510', 2, 'Pour this mixture into a large bowl upon chopped ice.');
