INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_696828dc51b7248d553f8c', 0, 'Three lumps of clear ice in a glass pitcher, the juice of half a lemon, one jigger orgeat syrup, half a pony brandy, half a pony maraschino, half a pony Jamaica rum, one tablespoonful fine sugar; add one iced bottle champagne, one bottle cold plain soda.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_696828dc51b7248d553f8c', 1, 'Mix well, ornament with fruit in season, put a few sprigs fresh mint on top.');
