INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_82928d0c49cf933ea9cebd', 'Absinthe Frappe, No. 1', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 5, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Take two mixing-glasses and fill them full of fine ice, pour into one of them one pony absinthe, one pony water, add two dashes anisette. Turn the other mixing-glass full of fine ice on top of first glass, then reverse the glasses, so as to allow the liquid to flow from one glass to the other. Repeat this until the liquid is very cold, then strain into a fancy bar-glass and add a squirt of seltzer.', NULL, NULL, 'coupe', 'frappe', NULL, 25, 'unreviewed');
