INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f994596a83b4fbab61c9e3', 'Raspberry Cream Frappe', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 5, 0, NULL, 'beverage', 1, 0, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'This delicious temperance drink is made in the following manner: Fill a long thin puDch-glass half-full fine ice, add one jigger raspberry syrup, fill up the glass two-thirds with cream or milk, then fill with siphon vichy; mix. Trim with fruit. Serve with straws. French Vermouth Frappe\ Fill two mixing-glasses with fine ice ; pour into one of them one jigger French vermouth. Turn the second glass on top of the first, reverse the glasses so as to allow the liquid to flow from one glass to the other, repeat this until the mixture is very cold, strain into a thin glass, add a squirt of seltzer.', NULL, NULL, 'coupe', 'frappe', 'seasonal fruit', NULL, 'unreviewed');
