INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3fb276bbca2024983bacda', 'Bonanza Punch (For a Party)', 'cocktail', '1895-era punch, served in ice with trim of fruit.', 1, 5, 2, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Five quarts cold water, four and one-half pounds of fine sugar, the juice of twelve lemons, three oranges, one can pineapple, one-half pint Tom gin, one pint white wine. Grate the rinds of three lemons and two oranges into a bowl, add the juice of the oranges and lemons. Put two quarts water, two pounds sugar, and the juice of pineapple on the fire, make a hot syrup of this, then pour it on the grated rinds and the juice to draw the flavor; chop the pineapple fine and add to mixture; stir well and strain all into a large punch-bowl half-full of very fine ice, add remainder of sugar and water, the gin, and wine; mix until cold, trim with fruit. Serve on ice with straws.', NULL, NULL, 'punch-bowl', 'hot-built', 'seasonal fruit', 12, 'unreviewed');
