INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_53b6aafd064d4404842b6f', 'Orange Ice', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 5, 2, NULL, 'cocktail', 1, 0, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Three pints of water, one pound of sugar, five or six sweet oranges, according to size, the juice of one lemon. Make a hot, thick syrup of sugar and very little water. Peel half the oranges, divide them each in twelve or more parts by natu- ral divisions, and drop the pieces of oranges in the boiling syrup. Grate the yellow part of the skin of the other three oranges in a bowl. Squeeze in the juice of the other oranges, add the syrup from the scalded orange slices, add water and lemon- juice to this syrup; mix, strain, and freeze; when half -finished stir in the sugared fruit.', NULL, NULL, 'coupe', 'hot-built', NULL, NULL, 'unreviewed');
