INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0010fd1f7af13f8801e73e', 'Bonanza Punch', 'cocktail', '1895-era punch, served in ice with trim of fruit.', 1, 5, 2, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Five quarts of water, four arid a half pounds of fine sugar, the juice of twelve lemons and three oranges, one can pineapple, one-half pint of Tom gin and one pint of Rhine wine. Grate the rinds of three lemons and two oranges into a bowl, add- ing the juice of all. Put two quarts of water, two pounds of fine sugar, and the juice of pine- apple on the fire and make a hot syrup of it. Pour this on the grated rinds and juice to draw flavor. Chop the pineapple very fine, and add to the mixture. Mix and strain all into freezer, add remainder of sugar, water; add gin and wine, and freeze. 114 MODERN AMERICAN DRINKS.', NULL, NULL, 'coupe', 'hot-built', NULL, 12, 'unreviewed');
