INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_c2fd8ec6162df1596a2293', 'Lemon Ginger Sherbet', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 5, 2, NULL, 'cocktail', 1, 0, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Use one quart boiling water, one pint sugar, four lemons and four ounces of candied ginger cut in fine pieces. Shave off the peel from two lemons in thin parings; be careful not to get any of the lighter colored rind below the cells. Put the par- ings into a bowl, add the boiling water, and let it stand ten minutes, closely covered. Cut the lemons in halves, squeeze out the juice and steep the finely cut ginger into it; then add all the sugar to the water. When cold strain and freeze.', NULL, NULL, 'coupe', 'hot-built', NULL, NULL, 'unreviewed');
