INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c2fd8ec6162df1596a2293', 0, 'Use one quart boiling water, one pint sugar, four lemons and four ounces of candied ginger cut in fine pieces.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c2fd8ec6162df1596a2293', 1, 'Shave off the peel from two lemons in thin parings; be careful not to get any of the lighter colored rind below the cells.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c2fd8ec6162df1596a2293', 2, 'Put the par- ings into a bowl, add the boiling water, and let it stand ten minutes, closely covered.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c2fd8ec6162df1596a2293', 3, 'Cut the lemons in halves, squeeze out the juice and steep the finely cut ginger into it; then add all the sugar to the water.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c2fd8ec6162df1596a2293', 4, 'When cold strain and freeze.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_329d94aafbd8558b1f9120', 'Pomegranate Sherbet', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 0, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Peel one dozen blood oranges, cut them in halves across the sections, remove the seeds and squeeze out the juice with a lemon squeezer. Add one pint of fine sugar and one quart water. Mix until the sugar is dissolved, then strain and freeze. 116 MODERN AMERICAN DRINKS.', NULL, NULL, 'coupe', 'stirred', NULL, NULL, 'unreviewed');
