INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_78a02fd9d0730b13373361', 'Punch, a la Vatican', 'cocktail', '1895-era punch, served in ice with trim of fruit.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Prepare a pineapple sherbet made tart with lemon-juice. Peel the lemons before squeezing so as not to get any of the oil of the rind into the juice. Mix the strained juice with the sherbet and freeze. Just before the punch is to be served add and mix into it one-half pint of old Jamaica rum and one pint of champagne for every two quarts of the sherbet.', NULL, NULL, 'coupe', 'stirred', NULL, 12, 'unreviewed');
