INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5c699f0aefd53715e4d19a', 'Shaddock, or Grape Fruit Sherbet', 'cocktail', 'Historic 1895 drink from Kappeler''s Modern American Drinks.', 1, 5, 2, NULL, 'cocktail', 1, 0, 1895, 'Modern American Drinks (George Kappeler, 1895)', 'New York, USA', 'George J. Kappeler', NULL, 'Soak one tablespoonful gelatin in a little cold water; take one pint of water and one pint fine sugar, boil for five minutes. Dissolve the soaked gelatin in the boiling syrup. Divide six shad- docks in halves across the sections, remove the seeds, and scoop out the pulp with a teaspoon. Leave all the membranous walls of the sections in the peel. Add the pulp to the cold syrup. Mix and freeze until mushy or hard, as preferred. MODERN AMERICAN DRINKS. 117', NULL, NULL, 'coupe', 'hot-built', NULL, NULL, 'unreviewed');
