INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c699f0aefd53715e4d19a', 1, 'Dissolve the soaked gelatin in the boiling syrup.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5c699f0aefd53715e4d19a', 2, 'Divide six shad- docks in halves across the sections, remove the seeds, and scoop out the pulp with a teaspoon.');
