INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_40cdee459e3e3f8e20cfc1', 'Brandy Punch', 'cocktail', '1878-era punch from the Criterion repertoire.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use learge twMer, One table-spoonful of raspberry syrup ; two tea-spoonfuls of white powdered sugar ; one wine glass of water ; one and a half wine glass of brandy ; one and a half small lemons ; two slices of orange ; one piece of pine-apple. Fill the tumbler with chipped ice, shake well, and dress the top with berries in season. Sip through a straw.', NULL, NULL, 'highball', 'shaken', 'seasonal berries', 14, 'unreviewed');
