INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b6ce5dc5f31ae4f7076c91', 3, 'Four bottles of Champagne make a gallon, and this is generally sufficient for fifteen persons in a mixed party.');
