INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0b67ab104c128a0fab85d4', 'Pine-Apple Punch', 'cocktail', '1878-era punch from the Criterion repertoire.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'For a Party of Ten, Four bottles of Champagne ; one pint of Jamaica rum ; one pint of brandy ; one gill of orange Curagoa ; the juice of four lemons ; four pine-apples sliced ; sweeten with a gill of plain syrup. Put the pine-apple, with one pound of sugar, in a bowl, and let them stand until the sugar is well soaked into the pine-apple, then add all the ingredients, except the Champagne ; place a large block of ice in the centre of the bowl, then add the Champagne, pouring it into the bowl at the side, so that it may effervesce as little as possible, and ornament with loaf sugar, sliced orange, aiid fruits in season ; serve in Champagne glasses as soon as made. Pine-apple Punch is sometimes made by adding sliced pine-apple to Brandy Punch. PUNCH. 21', NULL, NULL, 'punch-bowl', 'stirred', 'seasonal fruit', 14, 'unreviewed');
