INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_8ab9692a806da7e7e8e796', 4, 'are perfectly clean', 'are perfectly clean', NULL, 'bottles', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8ab9692a806da7e7e8e796', 0, 'In twenty quarts of I^''rench brandy put the peels of thirty^ lemons and thirty oranges, pared so thin that not the least of the white is left, infuse for twelve hours ; have ready thirty quarts of water that have been boiled but allowed to cool, put to it fifteen pounds of re- fined sugar, and when well mixed, pour it upon the brandy and peels, adding the juice of the oranges and of twenty-four lemons ; mix well^ then strain through a very fine hair-sieve into a very clean barrel that, has held spirits, and put into it two quarts of new milk, stir, and then bung it close.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8ab9692a806da7e7e8e796', 1, 'Let it stand six weeks in a warm cellar.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8ab9692a806da7e7e8e796', 2, 'Bottle the liquor for use, observing great care that the bottles are perfectly clean and dry, and the corks of the best quality, and well put in.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8ab9692a806da7e7e8e796', 3, 'This liquor will keep many years, and improve with age.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7d933c6834dcad09f6688d', 'Punch a la Romaine', 'cocktail', '1878-era punch from the Criterion repertoire.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'For a Party oj Fifteen* Take the juice of ten lemons and two sweet oranges ; dissolve in it two pounds of powdered sugar, and add the thin rind of an orange; run this through a sieve, and stir in by degrees the whites of ten eggs beaten into a froth. Put the bowl with the mix- ture into an ice pail, let it freeze a little, then stir briskly into it a bottle of Champagne and a bottle of Rum.', NULL, 'Contains raw egg. Use pasteurized eggs or omit for food-safety.', 'punch-bowl', 'stirred', NULL, 14, 'unreviewed');
