INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8b6315fba9081718e034b3', 1, 'Let it stand for twenty-four hours covered close.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8b6315fba9081718e034b3', 2, 'Add two pounds and a half of loaf sugar ; then strain it through a flannel bag tik quite fine, and bottle for use.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8b6315fba9081718e034b3', 3, 'It is fit for use as soon as bottled.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8b6315fba9081718e034b3', 4, 'EGG NOGG. •:o:- » Egg Nogg is a beverage of American origin, and has gained a popularity all over the world.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8b6315fba9081718e034b3', 5, 'In the South it is almost indispens- able at Christmas time, in the East the wise men imbibe it, in the West the egotist believes in it, and in the North it is a favourite at all seasons.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8b6315fba9081718e034b3', 6, 'In Scotland, Egg Nogg is known by the name of "Auld Man''s milk."');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_cee2baf6dfb6341417d28f', 'Baltimore Egg Nogg', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 8, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'For a Party of Fifteen.- Take the yolks of sixteen eggs, and twelve table-spoonfuls of powdered loaf sugar, and beat them to the consistency of cream ; to this add two-thirds of a nutmeg grated, and beat them together ; then mix in half a pint of brandy or Jamaica rum, and two wine glasses of Madeira. Have ready the whites of the eggs whipped to a stiff froth, which then beat into the mixture. When this is done, stir in six pints of rich milk. There is no heat used. Egg Nogg made in this manner is digestible, and will not cause headache. It makes an excellent drink for debilitated persons and a nourishing diet for consumptives.', NULL, 'Contains raw egg. Use pasteurized eggs or omit for food-safety.', 'collins', 'stirred', NULL, 14, 'unreviewed');
