INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f3a038c4de9e0a15090642', 'Mint Julep', 'cocktail', 'Classic mint julep style — over crushed ice with fruit.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use large tumbler. One table-spoonful of powdered sugar ; two table-spoonfuls of water ; mix well with a spoon ; take three or four sprigs of fresh mint and press them well in the sugar and water until the flavour of the mint is extracted ; add one and a half wine glass of Cognac, and fill the glass with fine chipped ice ; then draw out the sprigs of mint and insert them in the ice with the stems downward, so that the leaves will be above in the shape of a bouquet. Arrange berries and small pieces of sliced orange on top in a tasteful manner ; dash with Jamaica rum, and sprinkle white sugar on top. Sip through a straw, and you have a julep fit for an Emperor.', NULL, NULL, 'julep', 'muddled', 'mint sprigs', 22, 'unreviewed');
