INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f24c9fc8ade28eb115c8f4', 'Mulled Wine, Without Eggs', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'To every pint of wine allow one small tumbler of water ; sugar and spice to taste. In making preparations like the above, it is very difficult to give the exact proportions of ingredients like sugar and spice, as what quantity niight suit one person would be to another quite distasteful. Boil the spice in the water until the flavour is extracted, then add the wine and sugar, and bring the whole to the boiling point; then serve with strips of dry toast, or with biscuits. The spices usually used for Mulled Wine are cloves, grated nutmeg, cinnamon or mace. Any kind of wine may be mulled, but port or claret are those usually selected for the purpose, and the latter requires a larger proportion of sugar.', NULL, NULL, 'mug', 'hot-built', 'grated nutmeg', 12, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_f24c9fc8ade28eb115c8f4', 0, 'wine allow one small tumbler of water', 'wine allow one small tumbler of water', NULL, 'pint', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f24c9fc8ade28eb115c8f4', 0, 'To every pint of wine allow one small tumbler of water ; sugar and spice to taste.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f24c9fc8ade28eb115c8f4', 1, 'In making preparations like the above, it is very difficult to give the exact proportions of ingredients like sugar and spice, as what quantity niight suit one person would be to another quite distasteful.');
