INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_b0efed83ab344af14306b0', 'Ale Flip', 'cocktail', 'Egg-rich flip in the late-19th-century manner.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Put on the fire, in a saucepan, one quart of ale, and let it boil ; have ready the whites of two eggs and the yolks of four, well beaten up separately ; add them by degrees to four table-spoonfuls of moist sugar and half a nutmeg, grated. When all are well mixed, pour on the boiling ale by degrees, beating up the mixture continually, then pour it rapidly backwards and forwards from one jug to another, keeping one jug raised high above the other, till the fiip is smooth and finely frothed. This is a good and delightful remedy for a cold*', NULL, NULL, 'coupe', 'hot-built', NULL, 14, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b0efed83ab344af14306b0', 0, 'ale', 'ale', NULL, 'quart', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_b0efed83ab344af14306b0', 1, 'moist sugar', 'moist sugar', NULL, 'table spoonfuls', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b0efed83ab344af14306b0', 0, 'Put on the fire, in a saucepan, one quart of ale, and let it boil ; have ready the whites of two eggs and the yolks of four, well beaten up separately ; add them by degrees to four table-spoonfuls of moist sugar and half a nutmeg, grated.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b0efed83ab344af14306b0', 1, 'When all are well mixed, pour on the boiling ale by degrees, beating up the mixture continually, then pour it rapidly backwards and forwards from one jug to another, keeping one jug raised high above the other, till the fiip is smooth and finely frothed.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_b0efed83ab344af14306b0', 2, 'This is a good and delightful remedy for a cold*');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0fbd4eab53b6e36260bbe4', 'Egg Flip', 'cocktail', 'Egg-rich flip in the late-19th-century manner.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Put a quart of ale in a saucepan on the fire to boil. In the meantime, beat up the yolks of four eggs with the whites of two, adding four table-spoonfuls of brown sugar and a little nutmeg. Pour on the ale by degrees, beating up so as to prevent the mix- ture from curdling ; then pour backwards and forwards repeatedly from vessel to vessel, raising the hand to as great a height as possible, which process produces the smoothness and frothing essential to the good quality of fiip. This is excellent for a cold ; and, from its fleecy appearance, is sometimes designated ^''a yard of flannel"', NULL, NULL, 'coupe', 'hot-built', NULL, 14, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0fbd4eab53b6e36260bbe4', 0, 'ale', 'ale', NULL, 'quart', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0fbd4eab53b6e36260bbe4', 1, 'brown sugar', 'brown sugar', NULL, 'table spoonfuls', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0fbd4eab53b6e36260bbe4', 0, 'Put a quart of ale in a saucepan on the fire to boil.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0fbd4eab53b6e36260bbe4', 1, 'In the meantime, beat up the yolks of four eggs with the whites of two, adding four table-spoonfuls of brown sugar and a little nutmeg.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_0fbd4eab53b6e36260bbe4', 2, 'Pour on the ale by degrees, beating up so as to prevent the mix- ture from curdling ; then pour backwards and forwards repeatedly from vessel to vessel, raising the hand to as great a height as possible, which process produces the smoothness and frothing essential to the good quality of fiip.');
