INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_203ba23940c727b4dd2c2b', 'Egg Flip (No. 116)', 'cocktail', 'Egg-rich flip in the late-19th-century manner.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Another way. Beat up in a jug four new-laid eggs, omitting two of the whites ; add half a dozen lumps of sugar, and rub these well in the eggs. Pour in boiling water, about half a pint at a time ; and when the jug is nearly full, throw in two wine glasses of Cognac brandy ahd one wine glass of old Jamaica rum.', NULL, NULL, 'coupe', 'hot-built', NULL, 14, 'unreviewed');
