INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_4e7d47c188d93283760efe', 'Bottled Silk', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 5, 3, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'A bottle of Moselle; half a pint of sherry; the peel of a lemon not too much, so as to have the flavour predominate ; two table- spoonfuls of sugar, and a sprig of Verbena. All must be well mixed, and then strained and iced. 147 CHAMPAGNE, HOCK, or CHABLIS CUP. Dissolve four or five lumps of sugar in a quarter of a pint of boiling water, with a little very thin lemon peel ; let it stand a quarter of an hour ; add one bottle of the above wines and a sprig of Verbena; a small glass of sherry; half a pint of water. Mix well and let it stand half an hour. Strain and ice it well. 148 CIDER NECTAR, (a la Ritchie.) One quart of cider; one bottle of soda water; one glass of sherry; one wine glass of brandy; juice of half a lemon; peel of a quarter of a lemon ; sugar and nutmeg to taste ; a spring of Ver- bena. Flavour it to taste with pine-apple. Strain and ice it all well. This is a very delicious beverage.', NULL, NULL, 'coupe', 'hot-built', 'lemon peel', 18, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_4e7d47c188d93283760efe', 0, 'Moselle', 'moselle', NULL, 'bottle', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_4e7d47c188d93283760efe', 1, 'sherry', 'sherry', NULL, 'pint', 'bar');
