INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_34b43624cef2ac03fa54fa', 'Badminton', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Peel half of a medium-sized cucumber, and put it into a silver cup, with four ounces of powdered sugar, a little nutmeg, and a bottle of claret. When the sugar is thoroughly dissolved, pour in a bottle of soda-water, and it is fit for use.', NULL, NULL, 'coupe', 'stirred', NULL, 18, 'unreviewed');
