INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_347ca164c467fb1a511ce4', 'Blue Blazer', 'cocktail', 'Jerry Thomas''s flaming Scotch ritual, codified for British bartenders.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use two large silver plated Mugs with handles* One wine glass of Scotch whiskey ; one wine glass of boiling water. Put the whiskey and boiling water in one mug, ignite'' the liquid, and while blazing mix both ingredients by pouring them four or five times from one mug to the other. If well done, this will have the appearance of a continued stream of fire. Sweeten with one tea-spoonful of powdered white sugar, and serve in a small tumbler, with a piece of lemon.', NULL, NULL, 'mug', 'flamed', NULL, 35, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_347ca164c467fb1a511ce4', 0, 'Scotch whiskey', 'scotch whiskey', NULL, 'wine glass', 'bar');
