INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_347ca164c467fb1a511ce4', 0, 'Use two large silver plated Mugs with handles* One wine glass of Scotch whiskey ; one wine glass of boiling water.');
