INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3e914965830bc831b99699', 'Rhine Relish', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Fill large tumbler half full of Rhine wine, and fill ap with soda water. TEMPERANCE DRINKS. •:o:- "To be merry and wise" is a very good motto, and should be ever in our mind. We know perfectly well that in hot weather ardent spirits absorb and assimulate all the liquid that is left in the fevered frame, and it is to be regretted that in England there is no common usQ of such a harmless mixture as orgeat, or those pleasant, innocent beverages with which the Italians, in their cool arcades, consume long hours. When people are very hot they will drink, and the discussion of the subject may help to make drinks more wholesome. The simple use of the lemon, with really pure ice, is the one good which America has given us. We say the use of the lemon instead of lemonade, because cheap lemonade is often a mixture of impure water and chemical acid. The best thing of all for preventing the ills of hot weather is probably to abstain altogether from any iced drinks ; but, in the opinion of the thirsty, the remedy would be worse than the disease. — From the Globe newspaper.', NULL, NULL, 'coupe', 'stirred', NULL, 18, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_3e914965830bc831b99699', 0, 'half full of Rhine wine', 'half full of rhine wine', NULL, 'tumbler', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3e914965830bc831b99699', 0, 'Fill large tumbler half full of Rhine wine, and fill ap with soda water.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_3e914965830bc831b99699', 1, 'TEMPERANCE DRINKS. •:o:- "To be merry and wise" is a very good motto, and should be ever in our mind.');
