INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_c0d76497dbd33858c46159', 'Drink for the Dog Days', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 3, 0, NULL, 'beverage', 1, 0, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'A bottle of soda-water poured into a large goblet in which a lemon ice has been placed, forms a deliciously cool and refreshing drink, but should be taken with some care, and positively avoided whilst you are very hot.', NULL, NULL, 'coupe', 'stirred', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_c0d76497dbd33858c46159', 0, 'soda-water poured', 'soda-water poured', NULL, 'bottle', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_c0d76497dbd33858c46159', 0, 'A bottle of soda-water poured into a large goblet in which a lemon ice has been placed, forms a deliciously cool and refreshing drink, but should be taken with some care, and positively avoided whilst you are very hot.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_5842902d4a9f96268b1e9c', 'Soda Nectar-', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'Use large tumbler^ The juice of one lemon ; three quarters of a tumblerful of water ; powdered white sugar to taste ; half a tea-spoonful of carbonate of soda. Strain the juice of the lemon and add it to the water, with sufficient white sugar to sweeten the whole nicely. When well mixed, put in the soda, stir well, and drink while the mixture is in an effervescing state.', NULL, NULL, 'coupe', 'stirred', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_5842902d4a9f96268b1e9c', 0, 'carbonate of soda', 'carbonate of soda', NULL, 'tea spoonful', 'bar');
