INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7276414231e82670909dbb', 0, 'This simple but very nutritious drink may be taken by any person of the most delicate digestion, and has become one of the most popular delicacies since its introduction by me at Messrs.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7276414231e82670909dbb', 1, 'Spiers and Pond''^ Its mode of preparation is very simple; -''Into a wine glass put a new-laid Gg^ ; add half a tea-spoonful of jvindgar, dropping itgendy * down on the inside of the glass ; then drop on the yolk a little com- mon salt, sufficient not to quite cover half the size of a threepenny- piece; pepper according to taste.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7276414231e82670909dbb', 2, 'The way to take this should be by placing the glass with the vinegar furthest from the mouth and swallow the contents.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_7276414231e82670909dbb', 3, 'The vinegar being the last givesi It iXiore of an oyster-like flavour. - , Ai?/f.— This can be. taken with or without. the white of the egg^ according to taste. jt.!; >,.l... •''■> yo AMERICAN AKD OTHER DRINKS.');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a25e93d9975319cbee852d', 'Our Swizzle', 'cocktail', '1878 Engel drink, preserved verbatim from American and Other Drinks.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1878, 'American and Other Drinks (Leo Engel, 1878)', 'London, UK (Criterion Restaurant)', 'Leo Engel', 'Leo Engel was a celebrated American bartender who emigrated to London in the 1870s and presided over the bar at the Criterion Restaurant in Piccadilly Circus, where he introduced British drinkers to the craft of the American ''cooling drink.'' His 1878 compendium ''American and Other Drinks'' was one of the first British-published cocktail books, drawing from his lengthy sojourn in the United States and seasoned by Criterion house specialties. He is credited with popularizing the cocktail among the bon-vivants of late-Victorian London, from the Prince of Wales downwards.', 'It occurred to the Author of this little work, after a conversation with an Indian gentleman, to make a cocktail called in India a Swizzle, Take a small tumbler, half fill it with chipped ice ; then add one and a half liqueur glasses of Boker^s bitters ; half a wine glass of brandy ; and two or three drops of Noyeau to flavour and sweeten it. Now swizzle this concoction, with an Indian cane swizzle, to a froth ; drink through a strainer. Tastes differ. An Indian likes a cocktail swizzled ; a North American, within the last few years, will not take one unless it is stirred with a spoon; a South American will have it shaken; an Englishman, who has travelled in America, is more particular than any one of the others until you find out his taste, and is most difficult to please.', NULL, NULL, 'coupe', 'shaken', NULL, 18, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_a25e93d9975319cbee852d', 0, 'brandy', 'brandy', NULL, 'wine glass', 'bar');
