INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_7ffd15871313510f15f364', 'Vermouth Cocktail', 'cocktail', 'Pre-Prohibition cocktail from the Hoffman House Bartender''s Guide (1905).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1905, 'The Hoffman House Bartender''s Guide (Charles Mahoney, 1905)', 'New York, USA', 'Charles S. Mahoney', NULL, 'Use small bar glass.
