INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_9e7932a57723c9f2f4db8d', 'Champagne Cocktail', 'cocktail', 'Champagne cocktail from the Hoffman House.', 1, 3, 0, NULL, 'cocktail', 1, 1, 1905, 'The Hoffman House Bartender''s Guide (Charles Mahoney, 1905)', 'New York, USA', 'Charles S. Mahoney', 'Printed in Jerry Thomas''s 1862 guide but in use by the 1850s, featuring a sugar cube soaked in Angostura dropped into Champagne. The resulting slow bead of rising bitter bubbles makes it one of the simplest and oldest Champagne drinks. Humphrey Bogart orders it in Casablanca.', 'Pint bottle of wine makes three drinks.
Take one lump of sugar.
One or two dashes of Angostura bitters.
One small lump of ice.
Till the goblet with wine, stir up with a spoon,
and 5crve with a thin piece of twisted lemon peel.
A quart bottle of wine will make six cocktails.', NULL, NULL, 'flute', 'stirred', 'lemon peel', 12, 'unreviewed');
