INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_804712bca3c922211bc89f', 'Christmas punch pour 20 personnes', 'cocktail', 'Punch from Newman''s American Bar (Paris, 1904).', 8, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Dans un bol à punch en métal, préparer une heure
avant de servir :
1/4 de litre de marasquin,
1/2 litre de madère,
1/2 litre de curaçao,
1/4 litre de sirop d''ananas,
1 bouteille de vin du Rhin,
jus de 4 citrons et 2 oranges,
10 tranches de concombres,
10 tranches d''oranges,
10 tranches d''ananas,
500 grammes de fruits frais, raisin, cerises,
fraises des bois et groseilles.
Mettre rafraîchir une heure dans une glacière ou, à dé
faut, dans la glace pilée, remuer légèrement pour ne pas
écraser les fruits, tous les quarts d''heure ; ajouter au
moment de servir 3 bouteilles de Champagne, Grand
Idéal Brut 1889, servir dans des coupes.', NULL, NULL, 'punch', 'stirred', NULL, 12, 'unreviewed');
