INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0b705e48383743650ad2d7', 'Fancy Bénédictine Cocktail', 'cocktail', 'Pre-Prohibition cocktail from Frank Newman''s Paris-American bar (1904).', 1, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Verre n° 5
Prendre le verre n» 5, en sucrer les parois en passant
légèrement les bords extérieurs sur une tranche de citron,
tremper dans le sucre en poudre, mettre une cerise au
fond du verre, ensuite prendre un gobelet en argent, y
mettre un peu de glace pilée :
3 traits d''angostura.
Finir avec Bénédictine et eau, quantités égales.
Adapter un autre gobelet, frapper fortement, passer
dans le verre préparé, servir.', NULL, NULL, 'coupe', 'shaken', 'lemon slice', 28, 'unreviewed');
