INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_38b2db5ff4053da6f9cb10', 1, 'Remplir le verre avec du Champagne, remuer douce ment avec une cuillère pour ne pas écraser les fruits, ser vir avec une cuillère à café.');
