INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_88301df545e0836fd5190c', 0, 'Pour 10 personnes Préparer dans un bol en métal, une heure avant de ser vir Couper sur toute la longueur d''un concombre 2 zestes, 123 grammes de sucre en poudre, 1 bouteille de soda pour fondre le sucre, le jus de 4 limons, 2 bouteille de bordeaux, 1/4 de bouteille de cherry-brandy, 1/4 de bouteille de cognac, 2 verres à madère de sirop de groseille, 2 verres à madère de curaçao.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_88301df545e0836fd5190c', 1, 'Remuer, couper 5 tranches d''orange, 5 tranches de li mon, 5 tranches de concombre, 250 grammes de fruits de la saison, faire rafraîchir pendant une heure dans une glacière, ou, à défaut, mettre le bol dans la glace pilée, re muer tous les quarts d''heure sans écraser les fruits, reti rer les zestes de concombre, ajouter, au moment de servir, 1 bouteille de Champagne, Bulteaux 1893, servir.');
