INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_84a1eb328ae24f22484ddc', 0, 'Verre n" 5 Prendre le verre à mélange n» 1, mettre quelques mor ceaux de glace : 3 traits d''orange bitter, 2 traits de curaçao.');
