INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_181e487b1f3b698cfca015', 1, 'Adapter un second gobelet, frapper fortement, passer dans le verre n° 6, servir.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_181e487b1f3b698cfca015', 2, 'Nota. — Lorsqu''on fait pour plusieurs verres de cette consoin- mation, remplacer le lait par un jaune d''œuf, ce qui est la vraie recette du night cap ; pour un seul verre, il est impossible de mettre un jaune d''œuf, car ce serait n-op.');
