INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d2913200ead4baa60944ed', 'Xérès punch', 'cocktail', 'Punch from Newman''s American Bar (Paris, 1904).', 8, 3, 0, NULL, 'cocktail', 1, 1, 1904, 'American Bar (Frank P. Newman, 1904)', 'Paris, France', 'Frank P. Newman', NULL, 'Pour 30 personnes
Préparer dans un bol en métal, une heure avant de ser
vir
2 cuillerées à bouche de sucre en poudre,
1 verre à madère de crème de vanille Gusenier,
2 bouteilles de Xérès,
1/4 bouteille de cognac,
2 verres à madère de curaçao blanc.
Remuer, couper une orange en tranches minces, 5 tran
ches de citron, 2 tranches d''ananas, 2oO grammes de
fruits frais, faire rafraîchir dans une glacière, ou,à défaut,
mettre le bol dans delaglace pilée, remuer tous les quarts
d''heure, doucement pour ne pas écraser les fruits, servir
dans des verres à madère.', NULL, NULL, 'punch', 'stirred', NULL, 12, 'unreviewed');
