INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d2913200ead4baa60944ed', 3, 'cognac', 'cognac', 0.25, 'bottle', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d2913200ead4baa60944ed', 4, 'curaçao blanc', 'curaao blanc', 2, 'wine-glass', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2913200ead4baa60944ed', 0, 'Pour 30 personnes Préparer dans un bol en métal, une heure avant de ser vir 2 cuillerées à bouche de sucre en poudre, 1 verre à madère de crème de vanille Gusenier, 2 bouteilles de Xérès, 1/4 bouteille de cognac, 2 verres à madère de curaçao blanc.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2913200ead4baa60944ed', 1, 'Remuer, couper une orange en tranches minces, 5 tran ches de citron, 2 tranches d''ananas, 2oO grammes de fruits frais, faire rafraîchir dans une glacière, ou,à défaut, mettre le bol dans delaglace pilée, remuer tous les quarts d''heure, doucement pour ne pas écraser les fruits, servir dans des verres à madère.');
