INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_890edaff4bf46ef4d611a8', 'Chrysanthemum tea', 'drink', 'Chrysanthemum tea is a flower-based infusion beverage made from the chrysanthemum flowers of the species Chrysanthemum morifolium or Chrysanthemum indicum, which are most popular throughout East and Southeast Asia. First cultivated in China as a herb as early as the 1500 BCE, Chrysanthemum became popularized as a tea during the Song dynasty.', 1, 5, 15, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'brewed', NULL, NULL, 'unreviewed');
