INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_4e814ff409d57d8ae327ea', 'Cendol', 'drink', 'Cendol, also known as lot chong (Thai: ลอดช่อง), mont let saung (Burmese: မုန့်လက်ဆောင်း), nom lut (Khmer: បង្អែមលត), lod song (Lao: ລອດຊ່ອງ) and bánh lọt, is a traditional Southeast Asian dessert characterised by soft, green, worm-like jelly strands made from rice flour or mung bean starch, coconut milk and palm sugar syrup, typically served over shaved ice. The jelly is flavoured with pandan and combined with a creamy coconut milk base and the caramel-like sweetness of palm sugar.', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
