INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6a28a5c22087110de0e994', 'Cuban espresso', 'drink', 'Cuban espresso, also known as Café Cubano (or Colada, Cuban coffee, cafecito, Cuban pull, and Cuban shot), is a type of espresso that originated in Cuba. Specifically, it refers to an espresso shot which is sweetened (traditionally with natural brown sugar whipped with the first and strongest drops of espresso).', 1, 5, 0, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'shot', 'built', NULL, NULL, 'unreviewed');
