INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_bf11deac1b25583011295d', 'Raf coffee', 'drink', 'Raf coffee (Russian: раф-кофе) is a popular coffee drink in some countries of the former USSR, which appeared in the late 1990s in Russia. It is prepared by adding cream and vanilla sugar to a single shot of espresso and then foaming the mix with the espresso machine''s steam wand.', 1, 5, 0, 'https://upload.wikimedia.org/wikipedia/commons/1/1a/Rafcoffe.jpg', 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'shot', 'built', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_bf11deac1b25583011295d', 0, 'raf coffee', 'raf coffee', 1, 'serving', 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_bf11deac1b25583011295d', 0, 'It is prepared by adding cream and vanilla sugar to a single shot of espresso and then foaming the mix with the espresso machine''s steam wand.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_bf11deac1b25583011295d', 1, 'The main differences from a latte are the use of vanilla sugar and cream instead of milk and the fact that the whole mix is foamed together instead of just milk.');
