INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_a2b8efdf0e2de4f8c04bde', 'Soured milk', 'drink', 'Soured milk, sour milk, spontaneously soured milk, or naturally soured milk is the milk product fermented with indigenous microorganisms (chiefly mesophilic lactic acid bacteria), as opposed to cultured milk of which the production involves controlled fermentation with starter cultures. Lactic acid produced by the bacteria causes milk to coagulate and thicken, inhibiting the growth of harmful bacteria and improving the product''s shelf life.', 1, 5, 15, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'fermented', NULL, NULL, 'unreviewed');
