INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_c2c7e6ae08414ef98f117d', 'Tarkhuna', 'drink', 'Tarkhuna (Georgian: ტარხუნა, Georgian pronunciation: [tʼaɾχuna]; Russian: Тархуна) is a Georgian carbonated tarragon and/or woodruff-flavored soft drink, first ever created in 1887 in Kutaisi by  Georgian pharmacist Mitrofan Lagidze. Mitrofan Lagidze began to add odorous chukhpuch containing extract of Caucasian tarragon to sparkling water with natural syrups of his own production.', 1, 5, 0, 'https://upload.wikimedia.org/wikipedia/commons/3/32/%E9%BE%99%E8%92%BF%E6%B1%BD%E6%B0%B4.jpg', 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'rocks', 'built', NULL, NULL, 'unreviewed');
