INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2faa4cfa3f989de6234cbc', 'Fermented tea', 'drink', 'Fermented tea (also known as post-fermented tea or dark tea) is a class of tea that has undergone microbial fermentation, from several months to many years. The exposure of the tea leaves to humidity and oxygen during the process also causes endo-oxidation (derived from the tea-leaf enzymes themselves) and exo-oxidation (which is microbially catalysed).', 1, 5, 15, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'fermented', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2faa4cfa3f989de6234cbc', 0, 'them become darker with oxidation', 'them become darker with oxidation', 1, 'part', 'pantry');
