INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_49538845fe9570b23f66e4', 'Goishicha', 'drink', 'Goishicha (Japanese: 碁石茶 ''go-pebble tea'') is a fermented tea originally from China but now grown only in Ōtoyo, Kōchi and Ishizuchi-Kurocha, Ehime prefecture. The tea is made by fermenting harvested tea in a two-step process, first with aerobic fungi, then with anaerobic bacteria.', 1, 5, 15, NULL, 'drink', 0, 0, NULL, 'Wikipedia (CC BY-SA 4.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'mug', 'fermented', NULL, NULL, 'unreviewed');
