INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d83e7389bd616f1f14c1df', 0, 'Among the famous Rhode Island creameries which serve them are Delekta Pharmacy in Warren, and the Original Vanilla Bean in South Kingstown.');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d83e7389bd616f1f14c1df', 1, 'Newport Creamery, a chain of family restaurants found almost exclusively in Rhode Island, serve a variation of cabinets made with ice milk under the brand name "Awful Awful".');
