INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_889ede89c40974e7caa9da', 'Cider Cup—(without Liquor)', 'cocktail', 'Wine cup from Straub''s 1914 "Drinks."', 1, 8, 0, NULL, 'cocktail', 1, 1, 1914, 'Drinks (Jacques Straub, 1914)', 'Chicago / Kentucky, USA', 'Jacques Straub', 'Jacques Straub was head steward at the Pendennis Club in Louisville and later wine steward at Chicago''s Blackstone Hotel. His 1914 pocket manual, endorsed by Oscar Tschirky (the legendary Waldorf-Astoria maitre d''), compiled about seven hundred recipes from the best hotels, clubs and buffets of the pre-Prohibition era.', 'Cider Cup—(Without Liquor)

Use large glass pitcher.

Juice of 2 lemons or limes.

Juice of 1 orange.

1 jigger grenadine syrup.

1 jigger of plain syrup.

1 large piece of cube ice.

3 or 4 slices of lemon.

4 slices of orange.

4 slices of pineapple.

2 pieces of cucumber rind.
y 2 dozen cherries.

1 quart champagne cider.

Stir well with long spoon; put 1 bunch of mint
on top. Serve in Delmonico glass.', NULL, NULL, 'fizz', 'stirred', 'mint sprig, cherry', 12, 'unreviewed');
