INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1b28dcb32565233dcdda9d', 'Regent Punch', 'cocktail', 'Single-serving punch from Straub''s 1914 "Drinks."', 16, 20, 0, NULL, 'cocktail', 1, 1, 1914, 'Drinks (Jacques Straub, 1914)', 'Chicago / Kentucky, USA', 'Jacques Straub', 'Jacques Straub was head steward at the Pendennis Club in Louisville and later wine steward at Chicago''s Blackstone Hotel. His 1914 pocket manual, endorsed by Oscar Tschirky (the legendary Waldorf-Astoria maitre d''), compiled about seven hundred recipes from the best hotels, clubs and buffets of the pre-Prohibition era.', 'Regent Punch

1 lemon, sliced.

1 orange, sliced.

1 can pineapple and juice.

% pint St. Croix rum.

% pint rye whiskey.

18 lumps of sugar.

Mix in punch bowl and let stand 2 hours in
cold place; then add quickly 1 pint of tea and
mix slowly with above.

When ready to serve set on table and add 1
quart of champagne.', NULL, NULL, 'punch_bowl', 'built', 'pineapple', 12, 'unreviewed');
