INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 0, 'Combine sugar and 3/4 cup water in a small saucepan');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 1, 'Bring to a boil, stirring constantly');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 2, 'Reduce heat and simmer until all sugar is dissolved');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 3, 'Remove from heat and cool');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 4, 'In an aging container, combine apricot halves, almond extract, grain alcohol with 1/2 cup water, and brandy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 5, 'Stir in cooled sugar syrup mixture');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 6, 'Cap and let age for 2 days');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 7, 'Remove apricot halves. (Save apricot halves, can be used for cooking)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 8, 'Add food coloring and glycerine');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 9, 'Stir, recap and continue aging for 1 to 2 months');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 10, 'Re-bottle as desired');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d2d57cd3d2da5dbf8417f3', 11, 'Liqueur is ready to serve but will continue to improve with additional aging');
