INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 0, 'Pare very thinly the bright-colored rind from the oranges (no white)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 1, 'Blot the peel on paper towels to remove any excess oil');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 2, 'Put peel in a 4 cup screw-top jar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_01b8753c7c4bb46dad9945', 3, 'Add 2 cups vodka');
