INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_59e15c7166d5d39af570e4', 'Boilermaker', 'cocktail', 'The ''''''boilermaker'''''' consists of a shot of whiskey and a glass of beer.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, 'shot', NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_59e15c7166d5d39af570e4', 0, 'American Pilsner', 'american pilsner', 1, 'pint', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_59e15c7166d5d39af570e4', 1, 'Tennessee Whiskey (or Bourbon)', 'tennessee whiskey or bourbon', 1.5, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_59e15c7166d5d39af570e4', 0, 'Generally, the shot of whiskey and beer are served separately to the customer.  There is more than one way to consume this drink; one can:');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_59e15c7166d5d39af570e4', 1, 'Shoot the whiskey and then drink the beer');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_59e15c7166d5d39af570e4', 2, 'Pour the whiskey in the beer');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_59e15c7166d5d39af570e4', 3, 'Take the whiskey as a "depth shot," that is, drop the shot glass into the beer, causing the beer to foam up, and then chug the result.  Note that this is not exactly the safest procedure, especially after a few drinks; if the shot glass breaks when dropped, it may go unnoticed until the glass shards hit the throat');
