INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_bc86b0e7713f6358f1d9d1', 1, 'Divide a tall shot glass into thirds');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_bc86b0e7713f6358f1d9d1', 2, 'Fill the lowest third with grenadine syrup, the middle third with creme de menthe, and float the 151 in the top third');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_bc86b0e7713f6358f1d9d1', 3, 'Wet a thin straw, light the 151 by passing a lighter over it');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_bc86b0e7713f6358f1d9d1', 4, 'Plunge the straw to the bottom of the glass into the grenadine syrup and suck. If done rapidly and correctly the straw will not melt, and you can observe flames travelling up the inside of it. Stop sucking when the flame is inside the straw');
