INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d0eeec57b4a92610f1f870', 1, '½ cup (120 ml) sugar', ' cup 120 ml sugar', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d0eeec57b4a92610f1f870', 2, 'tablespoons (30 ml) rock salt', 'tablespoons 30 ml rock salt', 2, 'level', 'pantry');
