INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 2, 'Add the rinsed hibiscus petals, grated ginger, cloves, and cinnamon stick. Stir well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_8d15d45d455da261acff1f', 3, 'Let the mixture boil for about 5–7 minutes, or until the water turns a rich deep red and the spices have released their aroma');
