INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_55034d69dc6ab04dd5c34f', 0, 'Grind the almonds finely in blender');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_55034d69dc6ab04dd5c34f', 1, 'Add the water and continue to grind');
