INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_29efe4a11f32c7e9d97d50', 'Nigerian Tiger Nut Milk (Kunun Aya)', 'cocktail', '''''''Tiger nut milk'''''', locally known as ''''''kunun aya'''''', is a refreshing traditional beverage commonly consumed in Northern Nigeria. It is made from blended tiger nuts and often sweetened with dates or other natural sweeteners.', 1, 5, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikibooks (CC-BY-SA 3.0)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_29efe4a11f32c7e9d97d50', 0, 'tiger nuts', 'tiger nuts', 1, 'cup', 'pantry');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_29efe4a11f32c7e9d97d50', 1, 'water', 'water', 4, 'cup', 'pantry');
