INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_29efe4a11f32c7e9d97d50', 3, 'inch (2.5 cm) piece of fresh ginger, peeled', 'inch 25 cm piece of fresh ginger peeled', 1, 'piece', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_29efe4a11f32c7e9d97d50', 4, 'Sweetener of choice (e.g., honey or sugar), to taste', 'sweetener of choice eg honey or sugar to taste', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_29efe4a11f32c7e9d97d50', 0, 'Rinse and soak the tiger nuts in 2 cups of water for at least 24 hours to soften');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_29efe4a11f32c7e9d97d50', 1, 'Drain and blend the soaked tiger nuts with the dates and ginger, adding water as needed to form a smooth paste');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_29efe4a11f32c7e9d97d50', 2, 'Strain the blended mixture using a fine mesh sieve or cheesecloth to remove the chaff');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_29efe4a11f32c7e9d97d50', 3, 'Dilute the extracted milk with the remaining water to the desired consistency');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_29efe4a11f32c7e9d97d50', 4, 'Add your preferred sweetener to taste, and stir well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_29efe4a11f32c7e9d97d50', 5, 'Serve chilled. Refrigerate leftovers and consume within 1–2 days');
