INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 0, 'Pre-soak your almonds in water for 1 hour and then drain');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 1, 'Cut potatoes 5 cm chunks. Place the chunks into saucepan with enough water to fully cover them');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 2, 'Bring the saucepan to a simmer over high heat, and simmer for around 15 minutes until tender');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 3, 'Drain the potatoes. Transfer to blender with the almonds, vanilla, maple syrup, and salt. Add the water, and blend until smooth on a high speed, adding more water as necessary');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 4, 'Stretch the cheesecloth over a large bowl, and pour your mixture into it. Use a fork to agitate as needed, and let the milk drain through');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 5, 'When strained, taste the milk. Adjust by adding more water, vanilla, salt, or maple syrup as needed, depending on your taste');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_da27f7c0cbfda035dd31b1', 6, 'Chill and serve, shaking the mixture beforehand');
