INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_cfe85815a6fc28e63bf026', 2, 'Using a rolling pin, roll over the rosemary sprigs a few times on a chopping board to release the oils');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_cfe85815a6fc28e63bf026', 3, 'Add the rosemary to the pan with ginger, sugar, and water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_cfe85815a6fc28e63bf026', 4, 'Heat for 5 minutes over a low-medium heat, stirring occasionally, to dissolve the sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_cfe85815a6fc28e63bf026', 5, 'Reduce the heat to low and cook for 15 minutes until you get a slightly thick syrup. Leave it to cool, then use immediately or chill overnight to develop the flavors');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_cfe85815a6fc28e63bf026', 6, 'Strain the cordial syrup through a sieve into a bowl or jug. Transfer to a bottle');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_cfe85815a6fc28e63bf026', 7, 'To use, mix 1–2 tablespoons of cordial into ⅔ cup () of fizzy water to make a soda, or add to boiling water with 2 tablespoons of whiskey to make a hot toddy');
