INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f71244af75a23ded21d2ec', 0, 'Remove kefir grains from previous batch of starter, using a sieve or colander');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f71244af75a23ded21d2ec', 1, 'Shake kefir grains to remove excess kefir. Rinsing is not necessary (but optionally, rinse in fresh milk)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f71244af75a23ded21d2ec', 2, 'Place kefir grains in glass jar or jug with fresh milk. Generally, keep a ratio of kefir grains to milk of about 1:10 or 5% w/w');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_f71244af75a23ded21d2ec', 3, 'Set aside to ferment at room temperature (18–22°C) for 12–24 hours (see notes) until a smooth yoghurt-like consistency develops');
