INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_96e1308faec21e2e7f5c43', 5, '½–1 teaspoon each of any or all of these spices: cinnamon, nutmeg, cloves, caraw', '1 teaspoon each of any or all of these spices cinnamon nutmeg cloves caraway see', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_96e1308faec21e2e7f5c43', 0, 'Peel the oranges and lemons. Cut up the fruit and squeeze them into a crock pot. A garlic press or potato-ricer works, or some kind of juicer or fruit squeezer. Put the remaining fruit pulp into the crock pot as well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_96e1308faec21e2e7f5c43', 1, 'Add the raisins, honey, and spices. Stir. Do not add whiskey yet!');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_96e1308faec21e2e7f5c43', 2, 'Start the crock pot, and let the mixture cook for about 2–4 hours. Stir occasionally. It''s complete when the fruit pulp gets cooked down');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_96e1308faec21e2e7f5c43', 3, 'Strain into a pitcher. Mash down the fruit in the strainer to get all the liquid');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_96e1308faec21e2e7f5c43', 4, 'Add the whiskey to the pitcher and stir. If you cook the whiskey, even for a short time, the alcohol will start to evaporate. Taste, and add more whiskey to your liking');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_96e1308faec21e2e7f5c43', 5, 'Serve hot in shot glasses, espresso cups, or coffee mugs. After the first round, each individual serving can be reheated in the microwave');
