INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_1a54ddd32a82e91361fc9e', 2, '¾ oz fresh-squeezed lime juice', ' oz fresh-squeezed lime juice', 0, NULL, 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_1a54ddd32a82e91361fc9e', 3, '¾ oz simple syrup', ' oz simple syrup', 0, NULL, 'pantry');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1a54ddd32a82e91361fc9e', 0, 'Combine all ingredients except mint into a cocktail shaker, fill shaker with ice, and shake well');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1a54ddd32a82e91361fc9e', 1, 'Open shaker and add mint, leaving 1 mint leaf around the size of your thumb for garnish');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1a54ddd32a82e91361fc9e', 2, 'Close cocktail shaker and roll the mint from one end of the shaker to the other to gently express the mint oils but to not bruise the mint');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1a54ddd32a82e91361fc9e', 3, 'Use a hawthorn strainer and a fine mesh strainer to filter the contents into a chilled cocktail coupe');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_1a54ddd32a82e91361fc9e', 4, 'Garnish with the spare mint leaf you left aside');
