INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_1ba58937be655e1639b7aa', 3, 'Juice of 1–2 fresh lemons (optional, for added tanginess)', 'juice of 12 fresh lemons optional for added tanginess', 0, NULL, 'bar');
