INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 0, 'In a dry frying pan or skillet, toast the sesame seeds and peanut over medium heat. Stir them continuously to prevent burning until they turn golden brown and release their aroma');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 1, 'Remove the pan from the heat and let the toasted seeds and peanuts cool for a few minutes');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 2, 'In a blender, combine the toasted sesame seeds and peanuts with the water');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 3, 'Blend the mixture until it becomes smooth and creamy');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 4, 'Pour the mixture through a nut milk bag or fine mesh strainer into a large bowl to separate the liquid from the solids');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 5, 'Squeeze or press the bag to extract as much liquid as possible');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 6, 'Sweeten with the honey. Stir well to dissolve the sweetener');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 7, 'Chill the drink in the refrigerator for at least an hour before serving');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_10f19cc914ee226307d69c', 8, 'Stir before serving, as it may naturally separate over time');
