INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_961f20849f70dd1f0a3231', 0, 'Steep the violets in hot water for at least 10 minutes or until it turns a dark blue hue. Strain and reserve the liquid');
