INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_961f20849f70dd1f0a3231', 3, 'Serve the lemon mixture over ice, and garnish with extra flowers. When ready to drink, pour the syrup into the lemon water and watch it turn from a dark blue to a bright pink color');
