INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_1b506f921607b37730a407', 'kogel mogel', 'cocktail', 'Kogel mogel is an egg-based homemade dessert once popular in parts of Europe. It is made from egg yolks, sugar, and flavourings such as honey, vanilla, cocoa or rum, similar to eggnog or zabaione. In its classic form it is served slightly chilled or at room temperature. Served warm or hot, it is considered a home remedy for sore throats. Variations include milk, honey and soda.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/c/c7/Kogel_mogel.JPG', 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
