INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_716884478feea5b39c993c', 'Futschi', 'cocktail', 'Futschi ist ein Longdrink, der aus Cola und Weinbrand oder Weinbrand-Verschnitt gemischt wird. Futschi wird hauptsächlich in Kneipen in Berlin angeboten. Bis zur Wiedervereinigung im Jahr 1990 galt Futschi als typisch West-Berliner Getränk. Unter anderen Namen war beziehungsweise ist die Mischung von Cola und Weinbrand auch im übrigen Deutschland und in anderen Ländern bekannt.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', 'West Berlin', NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
