INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_cb31c0fc787193fae721c8', 0, 'brandy', 'brandy', 0, NULL, 'bar');
