INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_bfa6f1efc28bb9397c2591', 'Goombay Smash', 'cocktail', 'Goombay Smash is a rum based beverage in the Bahamas. It is traditionally served in a sling or collins glass. The Goombay Smash was created by Emily Cooper, aka Miss Emily, at the Blue Bee Bar in New Plymouth. The original recipe is a secret, but it is believed to have contained coconut rum, dirty rum, apricot brandy, and pineapple juice. Imitators and variations commonly use rum, coconut and pineapple juice. Apricot liqueur is sometimes used and dark, amber or spiced rums are preferred. In place of coconut rum, coconut cream can be used. Other variations include Creme de...', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/9/9a/Goombay_Smash_upon_arrival_%285435890609%29.jpg', 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
