INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_c73dceded484d8020105e3', 'May wine', 'cocktail', 'May wine, also known as Maitrank, Maiwein, Maibowle and Waldmeisterbowle, is an aromatized wine popular in Germany, sometimes made into a punch. May wine is served in the spring, traditionally on the May Day holiday. The base is made by steeping the fragrant creeping herb sweet woodruff that grows in the forests of Northern Europe in a white German wine. It is the specialty of the town of Arlon, in the south of Belgium.', 1, 3, 0, 'https://upload.wikimedia.org/wikipedia/commons/b/b2/Maibowle_in_Dresden.jpg', 'cocktail', 0, 1, NULL, 'Wikidata + Wikipedia', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
