INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_6f4809cc39349117abeae4', '20th century (cocktail)', 'cocktail', 'The 20th century is a cocktail created in 1937 by a British bartender named C.A. Tuck, and named in honor of the celebrated 20th Century Limited train which ran between New York City and Chicago from 1902 until 1967. The recipe was first published in 1937 in the Café Royal Cocktail Book by William J Tarling, President of the United Kingdom Bartenders'' Guild and head bartender at the Café Royal.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, 20, 'unreviewed');
