INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_26a61a76a8e819e4e2ee7f', '7 and 7', 'cocktail', 'A Seven and Seven or 7 and 7 is a highball cocktail, a mixed alcoholic drink containing Seagram''s Seven Crown, which is a blended whiskey, and 7 Up, which is a lemon-lime soft drink. It is typically served with ice. It was one of the most popular drinks in the United States during the 1970s.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, 'collins', 'stirred', NULL, NULL, 'unreviewed');
