INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_3e54907e26ff067096c630', 'BLT cocktail', 'cocktail', 'A BLT cocktail is a cocktail made out of the contents of a BLT sandwich (bacon, lettuce and tomato), blended together with vodka. Variants on the drink include utilizing bacon vodka instead of traditional vodka, substituting liquor for lettuce, incorporating bacon salt, or including cucumber flavored vodka.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', 'Bacon salt', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_3e54907e26ff067096c630', 0, 'baconlettuce or liquortomatovodka or bacon vodka', 'baconlettuce or liquortomatovodka or bacon vodka', 0, NULL, 'bar');
