INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_0e78f45ca61f5b78703415', 'Bacardi cocktail', 'cocktail', 'The Bacardi cocktail is a cocktail made primarily with Bacardi Superior. It is served as a "pre-dinner" cocktail.', 1, 3, 0, NULL, 'cocktail', 0, 1, 1900, 'Wikipedia (CC-BY-SA)', 'Havana, Cuba', NULL, 'A rum daiquiri variant with grenadine that became so identified with the brand that a 1936 New York Supreme Court ruling required it be made with Bacardi rum specifically. It was a favorite of pre-Prohibition Americans making Havana pilgrimages. The ruling is one of cocktail history''s rare legal precedents.', NULL, NULL, NULL, 'martini', 'shaken', 'Lime', 19, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_0e78f45ca61f5b78703415', 0, 'white rum', 'white rum', 1.52, 'oz', 'bar');
