INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_632c61445fba465f6cc427', 'Bay breeze (cocktail)', 'cocktail', 'The bay breeze is a cocktail which has a Cape Codder as its base, with the addition of pineapple juice. The drink is also sometimes called a downeaster, Hawaiian sea breeze, or a Paul Joseph. This cocktail is similar to the sea breeze, an IBA Official Cocktail with grapefruit juice (rather than pineapple).', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'Polynesia', NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, 7, 'unreviewed');
