INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_12578402ed7b9fe07fe274', 'Black and tan', 'cocktail', 'A black and tan is a beer cocktail made by layering a pale beer (usually pale ale) and a dark beer (usually stout). In Ireland, the drink is called a half and half.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'Ireland', NULL, NULL, NULL, NULL, NULL, 'pint', 'layered', NULL, NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_12578402ed7b9fe07fe274', 0, 'pale ale or lager and stout or porter', 'pale ale or lager and stout or porter', 0, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_12578402ed7b9fe07fe274', 0, 'A black and tan is prepared by filling a glass halfway with pale ale, then adding stout to fill the glass completely');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_12578402ed7b9fe07fe274', 1, 'An upside-down tablespoon may be placed over the glass to avoid splashing and mixing the layers');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_12578402ed7b9fe07fe274', 2, 'A specially designed black-and-tan spoon is bent in the middle so that it can balance on the edge of the pint-glass for easier pouring');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_12578402ed7b9fe07fe274', 3, 'The "layering" of Guinness on top of the pale ale or lager is possible because of the lower relative density of the Guinness');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_12578402ed7b9fe07fe274', 4, 'Several American breweries currently make premixed black and tan, for example Yuengling makes a drink called Yuengling''s Original Black and Tan');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_9e6f11249b69c8e282844a', 'Black nail', 'cocktail', 'A black nail cocktail is a mixture of Irish Mist and Irish whiskey in roughly equal portions, being typically garnished with orange zest.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'Ireland', NULL, NULL, NULL, NULL, NULL, 'rocks', 'stirred', 'orange zest', 16, 'unreviewed');
