INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_110247a8d175e214d04ae5', 'Brandy Alexander', 'cocktail', 'A Brandy Alexander is a brandy-based dessert cocktail, consisting of cognac, crème de cacao, and cream, that became popular during the early 20th century. It is a variation of an earlier, gin-based cocktail called simply an Alexander. The cocktail known as Alexander today may contain gin or brandy. Ice cream can be added for a "frozen Brandy Alexander".', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'Sprinkle fresh ground nutmeg on top', 17, 'unreviewed');
