INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_00bc47c39328bbf893f4c8', 'Breakfast martini', 'cocktail', 'A breakfast martini is a marmalade cocktail with gin, marmalade, orange liqueur, and lemon juice (in place of vermouth), created by bartender Salvatore Calabrese. Although the drink contains no vermouth, the term "breakfast martini" is consistent with the trend of calling any straight liquor in a martini glass a "martini," such as the saketini or other variations.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'lemon twist', NULL, 'unreviewed');
