INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_b43a8a8cd4faf4f01648dd', 'Bronx (cocktail)', 'cocktail', 'The Bronx is a cocktail. It is essentially a Martini with orange juice added. It was ranked number three in "The World''s 10 Most Famous Cocktails in 1934" behind the Martini (#1) and the Manhattan (#2). In the 1934 movie "The Thin Man", the lead actor (William Powell) compared the methods for shaking the Manhattan, the Bronx and the Martini.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'orange twist', 18, 'unreviewed');
