INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_66db40a1d9d7e25117778c', 'Champagne cocktail', 'cocktail', 'A champagne cocktail is an alcoholic cocktail made with sugar, Angostura bitters, champagne, brandy, and a maraschino cherry as a garnish. It is one of the IBA official cocktails. Other variations include grenadine, orange bitters, cognac (substitute of brandy) or sparkling wine (substitute for champagne). Other possible garnishes include strawberries or dried orange slices.', 1, 3, 0, NULL, 'cocktail', 0, 1, 1855, 'Wikipedia (CC-BY-SA)', 'USA/France', NULL, 'Printed in Jerry Thomas''s 1862 guide but in use by the 1850s, featuring a sugar cube soaked in Angostura dropped into Champagne. The resulting slow bead of rising bitter bubbles makes it one of the simplest and oldest Champagne drinks. Humphrey Bogart orders it in Casablanca.', NULL, NULL, NULL, 'flute', 'shaken', 'Orange slice and maraschino cherry', 12, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_66db40a1d9d7e25117778c', 0, 'champagne', 'champagne', 3.04, 'oz', 'bar');
