INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_595b2fcb9b5c0e1a597712', 'Chartreuse swizzle', 'cocktail', 'The Chartreuse swizzle is a tiki cocktail made with green Chartreuse, velvet falernum, pineapple juice, and lime juice. Invented in 2003 by American bartender Marcovaldo Dionysos of San Francisco cocktail bar Harry Denton''s Starlight Room, the cocktail has since emerged as a modern classic. It has been recognized by the International Bartenders Association as an official cocktail since 2024.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, 'collins', 'stirred', NULL, 18, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_595b2fcb9b5c0e1a597712', 0, 'green chartreuse', 'green chartreuse', 1.52, 'oz', 'bar');
