INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_ef7da151509b8346c9664d', 'Cheeky Vimto', 'cocktail', 'A Cheeky Vimto is an alcoholic drink cocktail with taste similar to the soft drink Vimto, despite Vimto not being one of its ingredients.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, 2, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef7da151509b8346c9664d', 0, 'blue wkd', 'blue wkd', 9.3, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_ef7da151509b8346c9664d', 1, 'port', 'port', 1.69, 'oz', 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 0, 'The cocktail is made up of ruby port and Blue WKD');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 1, 'Though the owners of Vimto decided they would not manufacture an alcopop version, the company has encouraged its use as a mixer');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 2, 'Many establishments give the Cheeky Vimto other names in order to avoid breaching the trademark of the soft drink');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 3, 'A variation consisting of the port and WKD, without the Vimto, was described in Amy Winehouse''s biography as one of her beverages of choice');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_ef7da151509b8346c9664d', 4, 'In May 2018 WKD released a canned version of their drink called "Cheeky V", described as "Port Blue and Lemonade Flavour"');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_21e3482187746165cddf87', 'Chiliguaro', 'cocktail', 'Chiliguaro is a popular alcoholic beverage in Costa Rica. It is made with guaro, a distilled cane sugar liquor which is traditional in Costa Rica, and combined with spicy chili sauce. Sometimes tomato juice, salt, lime, pepper and other ingredients used in Costa Rican cuisine.', 1, 3, 0, NULL, 'cocktail', 0, 0, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
