INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_83a6c7978fb78232c6ec84', 'Chrysanthemum (cocktail)', 'cocktail', 'The Chrysanthemum is a cocktail made with absinthe, Bénédictine, and vermouth. This pre-Prohibition Era cocktail is sometimes credited to the 1930 edition of The Savoy Cocktail Book, although an earlier recipe appears in the influential early 20th-century cocktail book Recipes for Mixed Drinks (1916) by Hugo R. Ensslin.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'coupe', 'stirred', 'Orange peel', 19, 'unreviewed');
