INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_f53099f543179473c2b609', 'Crémas', 'cocktail', 'Crémas (; ) also spelled Crémasse or Kremas, is a sweet and creamy alcoholic beverage native to Haiti. The beverage is made primarily from creamed coconut, sweetened condensed milk, evaporated milk, cinnamon, clove, nutmeg, vanilla essence, almond essence, lime, and Haitian rhum. It is typically enjoyed during the Christmas season.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'shaken', NULL, NULL, 'unreviewed');
