INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_2ae9166f15917fedfecdf9', 'Curaçao punch', 'cocktail', 'Curaçao punch is a cocktail that comes from Harry Johnson''s New and Improved Bartender''s Manual (1882), though a drink of that name was served in the Metropolitan Hotel in Washington, D.C. at least as early as 1867. Dale DeGroff, a notable bartender and author of The Craft of the Cocktail (Clarkson Potter, 2002), holds this to be his favorite forgotten potation.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'stirred', NULL, 21, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 0, '(7 ml) sugar', '7 ml sugar', 0.5, 'tbsp', 'condiment');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 1, 'or 3 dashes fresh lemon juice', 'or 3 dashes fresh lemon juice', 2, NULL, 'produce');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 2, '(1/4 gill, 3 cl) soda water', '14 gill 3 cl soda water', 1, 'oz', 'beverage');
