INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_2ae9166f15917fedfecdf9', 4, '(1/2 gill, 6 cl) orange curaçao', '12 gill 6 cl orange curaao', 2, 'oz', 'bar');
