INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2ae9166f15917fedfecdf9', 0, 'Preparation involves combining the sugar, lemon juice, and soda water, dissolving the sugar, pouring the drink into a glass with finely-shaved or crushed ice and then adding the remaining ingredients');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2ae9166f15917fedfecdf9', 1, 'The drink is then stirred and may be garnished with a variety of fruits');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_2ae9166f15917fedfecdf9', 2, '*1/2 tablespoon (7 ml) sugar (This indulged the major nineteenth-century sweet tooth-alter to taste.) *2 or 3 dashes fresh lemon juice (More of this can also compensate for the sweetness.) *1 ounce (1/4 gill, 3 cl) soda water *1 ounce (1/4 gill, 3 cl) brandy (Johnson calls for Martell cognac.) *2 ounce (1/2 gill, 6 cl) orange curaçao *1 ounce (1/4 gill, 3 cl) Jamaican rum (Dale suggests a full-bodied style of rum.)');
