INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_bf04cd8f4334fdd5b20998', 'Flaming Doctor Pepper', 'cocktail', 'A Flaming Doctor Pepper, or Flaming Dr Pepper, is a flaming cocktail with taste similar to the soft drink Dr Pepper, despite Dr Pepper not being one of its ingredients. Dave Brinks of the Gold Mine Saloon lays claim to inventing the drink.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'shot', 'layered', NULL, 14, 'unreviewed');
