INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_09deab8a08664d0b558d0d', 2, 'According to Burgess, "it tastes very smooth, induces a somewhat metaphysical elation, and rarely leaves a hangover."');
