INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_5e654e7c9104d4958ec9cf', 0, 'The whiskey is floated on top of the Irish cream in a shot glass, and the shot glass is then dropped into the stout');
