INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_75365133f07c3a1b52ad2e', 'Mimosa (cocktail)', 'cocktail', 'A mimosa cocktail consists of champagne (or other sparkling wine) and chilled citrus juice, usually orange juice. It is often served in a tall champagne flute at brunch, or at festive occasions such as weddings, or as part of business or first class service on some passenger railways and airlines. The mixing ratio varies.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', NULL, NULL, NULL, NULL, NULL, NULL, 'flute', 'shaken', 'Orange twist', 5, 'unreviewed');
