INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_839212054907880e608a82', 3, 'Drizzle syrup from cherries for added sweetness and colour');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_d60cd1ea02d2f29904b9ba', 'Queen''s Park Swizzle', 'cocktail', 'The Queen''s Park Swizzle is a classic rum cocktail that originated in Trinidad.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'Caribbean', NULL, NULL, NULL, NULL, NULL, 'collins', 'muddled', 'Mint sprig', NULL, 'unreviewed');
INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_d60cd1ea02d2f29904b9ba', 0, 'mint, lime juice, rum, angostura bitters, syrup, ice', 'mint lime juice rum angostura bitters syrup ice', 0, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d60cd1ea02d2f29904b9ba', 0, 'The drink is traditionally served in a Collins or highball glass');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d60cd1ea02d2f29904b9ba', 1, 'In the glass, mint leaves are muddled with lime juice and syrup (Demerara or simple)');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d60cd1ea02d2f29904b9ba', 2, 'Demerara rum, Angostura bitters, and then crushed ice is added');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d60cd1ea02d2f29904b9ba', 3, 'The drink is swizzled with a swizzle stick until the drink is mixed and the glass is completely frosted');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d60cd1ea02d2f29904b9ba', 4, 'A bar spoon can substitute the swizzle stick');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d60cd1ea02d2f29904b9ba', 5, 'The swizzle method allows the muddled mint to stay at the bottom');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_d60cd1ea02d2f29904b9ba', 6, 'Sometimes, bitters are added to the crushed ice to give the ice layer a red appearance, so that the drink will have green, gold, and red layers');
