INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_db68d93d7d801609e554b7', 2, 'Mix egg yolks with powdered sugar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_db68d93d7d801609e554b7', 3, 'Put a spoonful of yolk mixture in cup, and mix with brandy and rum');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_db68d93d7d801609e554b7', 4, 'Fold in some egg white, then add hot milk and top with more egg white');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_db68d93d7d801609e554b7', 5, 'Stir gently to fold in the egg white');
