INSERT OR IGNORE INTO recipe_ingredient (recipe_id, seq, name, canonical_name, quantity, unit, aisle) VALUES ('cck_fc50eac4c5ac88d0bebda0', 0, 'orange juice,wkd bluesouthern comfortvodka', 'orange juicewkd bluesouthern comfortvodka', 0, NULL, 'bar');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc50eac4c5ac88d0bebda0', 0, 'The drink is typically prepared in a pint glass, mixing one part vodka, one part Southern Comfort, a bottle of WKD Blue, and Orange Juice, mixed together until the drink is a luminous green');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc50eac4c5ac88d0bebda0', 1, 'Ice is optional');
INSERT OR IGNORE INTO recipe_step (recipe_id, seq, text) VALUES ('cck_fc50eac4c5ac88d0bebda0', 2, 'The drink can be served in any vessel, but most bars in Scotland will either serve it in pints or in a pitcher');
INSERT OR IGNORE INTO recipe (id, title, cuisine, description, servings, prep_minutes, cook_minutes, image_url, content_type, is_historic, is_alcoholic, source_year, source_book, source_region, contributor_name, contributor_story, original_text, modernized_text, safety_notes, glass_type, method, garnish, abv_percent, audit_status) VALUES ('cck_af827e963d71e9194b9375', 'Vesper (cocktail)', 'cocktail', 'The Vesper is a cocktail that was originally made of gin, vodka, and Kina Lillet. Since that form of Lillet is no longer produced, modern bartenders need to modify the recipe to mimic the original taste, with Lillet Blanc or Cocchi Americano as a typical substitute.', 1, 3, 0, NULL, 'cocktail', 0, 1, NULL, 'Wikipedia (CC-BY-SA)', 'United States', NULL, NULL, NULL, NULL, NULL, 'martini', 'shaken', 'lemon zest', 29, 'unreviewed');
